export default [{"id":"1474","jozz":"11","page":"221","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"9","line_end":"9","aya_no":"1","aya_text":"الٓرۚ كِتَٰبٌ أُحۡكِمَتۡ ءَايَٰتُهُۥ ثُمَّ فُصِّلَتۡ مِن لَّدُنۡ حَكِيمٍ خَبِيرٍ","aya_text_emlaey":"الر كتاب أحكمت آياته ثم فصلت من لدن حكيم خبير","aya_tafseer":"[1] الٓرۚ سبق الكلام على الحروف المقطَّعة في أول سورة البقرة.هذا الكتاب الذي أنزله الله على محمد -صلى الله عليه وسلم- أُحكمت آياته من الخلل والباطل، ثم بُيِّنت بالأمر والنهي وبيان الحلال والحرام من عند الله، الحكيم بتدبير الأمور، الخبير بما تؤول إليه عواقبها."},{"id":"1475","jozz":"11","page":"221","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"10","line_end":"10","aya_no":"2","aya_text":"أَلَّا تَعۡبُدُوٓاْ إِلَّا ٱللَّهَۚ إِنَّنِي لَكُم مِّنۡهُ نَذِيرٞ وَبَشِيرٞ","aya_text_emlaey":"ألا تعبدوا إلا الله إنني لكم منه نذير وبشير","aya_tafseer":"[2] وإنزال القرآن وبيان أحكامه وتفصيلها وإحكامها؛ لأجل أن لا تعبدوا إلا الله وحده لا شريك له. إنني لكم -أيها الناس- من عند الله نذير ينذركم عقابه، وبشير يبشِّركم بثوابه."},{"id":"1476","jozz":"11","page":"221","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"10","line_end":"13","aya_no":"3","aya_text":"وَأَنِ ٱسۡتَغۡفِرُواْ رَبَّكُمۡ ثُمَّ تُوبُوٓاْ إِلَيۡهِ يُمَتِّعۡكُم مَّتَٰعًا حَسَنًا إِلَىٰٓ أَجَلٖ مُّسَمّٗى وَيُؤۡتِ كُلَّ ذِي فَضۡلٖ فَضۡلَهُۥۖ وَإِن تَوَلَّوۡاْ فَإِنِّيٓ أَخَافُ عَلَيۡكُمۡ عَذَابَ يَوۡمٖ كَبِيرٍ","aya_text_emlaey":"وأن استغفروا ربكم ثم توبوا إليه يمتعكم متاعا حسنا إلى أجل مسمى ويؤت كل ذي فضل فضله وإن تولوا فإني أخاف عليكم عذاب يوم كبير","aya_tafseer":"[3] واسألوه أن يغفر لكم ذنوبكم، ثم ارجعوا إليه نادمين يمتعكم في دنياكم متاعاً حسناً بالحياة الطيبة فيها، إلى أن يحين أجلكم، ويعُطِ كل ذي فضل من علم وعمل جزاء فضله كاملاً لا نقص فيه، وإن تعرضوا عمَّا أدعوكم إليه فإني أخشى عليكم عذاب يوم شديد، وهو يوم القيامة. وهذا تهديد شديد لمن تولَّى عن أوامر الله تعالى وكذَّب رسله."},{"id":"1477","jozz":"11","page":"221","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"13","line_end":"13","aya_no":"4","aya_text":"إِلَى ٱللَّهِ مَرۡجِعُكُمۡۖ وَهُوَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٌ","aya_text_emlaey":"إلى الله مرجعكم وهو على كل شيء قدير","aya_tafseer":"[4] إلى الله رجوعكم بعد موتكم جميعاً فاحذروا عقابه، وهو سبحانه قادر على بعثكم وحشركم وجزائكم."},{"id":"1478","jozz":"11","page":"221","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"13","line_end":"15","aya_no":"5","aya_text":"أَلَآ إِنَّهُمۡ يَثۡنُونَ صُدُورَهُمۡ لِيَسۡتَخۡفُواْ مِنۡهُۚ أَلَا حِينَ يَسۡتَغۡشُونَ ثِيَابَهُمۡ يَعۡلَمُ مَا يُسِرُّونَ وَمَا يُعۡلِنُونَۚ إِنَّهُۥ عَلِيمُۢ بِذَاتِ ٱلصُّدُورِ","aya_text_emlaey":"ألا إنهم يثنون صدورهم ليستخفوا منه ألا حين يستغشون ثيابهم يعلم ما يسرون وما يعلنون إنه عليم بذات الصدور","aya_tafseer":"[5] إن هؤلاء المشركين يضمرون في صدورهم الكفر؛ ظنّاً منهم أنه يخفى على الله ما تضمره نفوسهم، ألا يعلمون حين يغطُّون أجسادهم بثيابهم أن الله لا يخفى عليه سِرُّهم وعلانيتهم؟ إنه عليم بكل ما تُكِنُّه صدورهم من النيات والضمائر والسرائر."},{"id":"1479","jozz":"12","page":"222","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"1","line_end":"2","aya_no":"6","aya_text":"۞ وَمَا مِن دَآبَّةٖ فِي ٱلۡأَرۡضِ إِلَّا عَلَى ٱللَّهِ رِزۡقُهَا وَيَعۡلَمُ مُسۡتَقَرَّهَا وَمُسۡتَوۡدَعَهَاۚ كُلّٞ فِي كِتَٰبٖ مُّبِينٖ","aya_text_emlaey":"وما من دابة في الأرض إلا على الله رزقها ويعلم مستقرها ومستودعها كل في كتاب مبين","aya_tafseer":"[6] لقد تكفَّل الله برزق جميع ما دبَّ على وجه الأرض، تفضلاً منه، ويعلم مكان استقراره في حياته وبعد موته، ويعلم الموضع الذي يموت فيه، كل ذلك مكتوب في كتاب عند الله مبين عن جميع ذلك."},{"id":"1480","jozz":"12","page":"222","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"2","line_end":"6","aya_no":"7","aya_text":"وَهُوَ ٱلَّذِي خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ فِي سِتَّةِ أَيَّامٖ وَكَانَ عَرۡشُهُۥ عَلَى ٱلۡمَآءِ لِيَبۡلُوَكُمۡ أَيُّكُمۡ أَحۡسَنُ عَمَلٗاۗ وَلَئِن قُلۡتَ إِنَّكُم مَّبۡعُوثُونَ مِنۢ بَعۡدِ ٱلۡمَوۡتِ لَيَقُولَنَّ ٱلَّذِينَ كَفَرُوٓاْ إِنۡ هَٰذَآ إِلَّا سِحۡرٞ مُّبِينٞ","aya_text_emlaey":"وهو الذي خلق السموات والأرض في ستة أيام وكان عرشه على الماء ليبلوكم أيكم أحسن عملا ولئن قلت إنكم مبعوثون من بعد الموت ليقولن الذين كفروا إن هذا إلا سحر مبين","aya_tafseer":"[7] وهو الذي خلق السموات والأرض وما فيهن في ستة أيام، وكان عرشه على الماء قبل ذلك؛ ليختبركم أيكم أحسن له طاعةً وعملاً، وهو ما كان خالصاً لله موافقاً لما كان عليه رسول الله -صلى الله عليه وسلم-. ولئن قلت -أيها الرسول- لهؤلاء المشركين من قومك: إنكم مبعوثون أحياءً بعد موتكم، لسارعوا إلى التكذيب وقالوا: ما هذا القرآن الذي تتلوه علينا إلا سحر بيِّن."},{"id":"1481","jozz":"12","page":"222","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"6","line_end":"8","aya_no":"8","aya_text":"وَلَئِنۡ أَخَّرۡنَا عَنۡهُمُ ٱلۡعَذَابَ إِلَىٰٓ أُمَّةٖ مَّعۡدُودَةٖ لَّيَقُولُنَّ مَا يَحۡبِسُهُۥٓۗ أَلَا يَوۡمَ يَأۡتِيهِمۡ لَيۡسَ مَصۡرُوفًا عَنۡهُمۡ وَحَاقَ بِهِم مَّا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ","aya_text_emlaey":"ولئن أخرنا عنهم العذاب إلى أمة معدودة ليقولن ما يحبسه ألا يوم يأتيهم ليس مصروفا عنهم وحاق بهم ما كانوا به يستهزئون","aya_tafseer":"[8] ولئن أخَّرنا عن هؤلاء المشركين العذاب إلى أجل معلوم فاستبطؤوه، ليقولُنَّ استهزاءً وتكذيباً: أي شيء يمنع هذا العذاب من الوقوع إن كان حقّاً؟ ألا يوم يأتيهم ذلك العذاب لا يستطيع أن يصرفه عنهم صارف، ولا يدفعه دافع، وأحاط بهم من كل جانب عذابُ ما كانوا يستهزئون به قبل وقوعه بهم."},{"id":"1482","jozz":"12","page":"222","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"9","line_end":"10","aya_no":"9","aya_text":"وَلَئِنۡ أَذَقۡنَا ٱلۡإِنسَٰنَ مِنَّا رَحۡمَةٗ ثُمَّ نَزَعۡنَٰهَا مِنۡهُ إِنَّهُۥ لَيَـُٔوسٞ كَفُورٞ","aya_text_emlaey":"ولئن أذقنا الإنسان منا رحمة ثم نـزعناها منه إنه ليئوس كفور","aya_tafseer":"[9] ولئن أعطينا الإنسان مِنَّا نعمة من صحة وأمن وغيرهما، ثم سلبناها منه، إنه لَشديد اليأس من رحمة الله، جَحود بالنعم التي أنعم الله بها عليه."},{"id":"1483","jozz":"12","page":"222","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"10","line_end":"11","aya_no":"10","aya_text":"وَلَئِنۡ أَذَقۡنَٰهُ نَعۡمَآءَ بَعۡدَ ضَرَّآءَ مَسَّتۡهُ لَيَقُولَنَّ ذَهَبَ ٱلسَّيِّـَٔاتُ عَنِّيٓۚ إِنَّهُۥ لَفَرِحٞ فَخُورٌ","aya_text_emlaey":"ولئن أذقناه نعماء بعد ضراء مسته ليقولن ذهب السيئات عني إنه لفرح فخور","aya_tafseer":"[10] ولئن بسطنا للإنسان في دنياه ووسَّعنا عليه في رزقه بعد ضيق من العيش، ليقولَنَّ عند ذلك: ذهب الضيق عني وزالت الشدائد، إنه لبَطِر بالنعم، مبالغ في الفخر والتعالي على الناس."},{"id":"1484","jozz":"12","page":"222","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"12","line_end":"13","aya_no":"11","aya_text":"إِلَّا ٱلَّذِينَ صَبَرُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ أُوْلَٰٓئِكَ لَهُم مَّغۡفِرَةٞ وَأَجۡرٞ كَبِيرٞ","aya_text_emlaey":"إلا الذين صبروا وعملوا الصالحات أولئك لهم مغفرة وأجر كبير","aya_tafseer":"[11] لكن الذين صبروا على ما أصابهم من الضراء، إيماناً بالله واحتساباً للأجر عنده، وعملوا الصالحات؛ شكراً لله على نعمه، هؤلاء لهم مغفرة لذنوبهم وأجر كبير في الآخرة."},{"id":"1485","jozz":"12","page":"222","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"13","line_end":"15","aya_no":"12","aya_text":"فَلَعَلَّكَ تَارِكُۢ بَعۡضَ مَا يُوحَىٰٓ إِلَيۡكَ وَضَآئِقُۢ بِهِۦ صَدۡرُكَ أَن يَقُولُواْ لَوۡلَآ أُنزِلَ عَلَيۡهِ كَنزٌ أَوۡ جَآءَ مَعَهُۥ مَلَكٌۚ إِنَّمَآ أَنتَ نَذِيرٞۚ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ وَكِيلٌ","aya_text_emlaey":"فلعلك تارك بعض ما يوحى إليك وضائق به صدرك أن يقولوا لولا أنـزل عليه كنـز أو جاء معه ملك إنما أنت نذير والله على كل شيء وكيل","aya_tafseer":"[12] فلعلك -أيها الرسول، لعظم ما تراه منهم من الكفر والتكذيب- تارك بعض ما يوحى إليك مما أنزله الله عليك وأمرك بتبليغه، ممَّا يَشُقُّ على المشركين سماعه ويثير غضبهم، وضائق به صدرك؛ خشية أن يطلبوا منك بعض المطالب على وجه التعنت، كأن يقولوا: لولا أُنزل عليه مال كثير، أو جاء معه ملك يصدقه في رسالته، فبلِّغهم ما أوحيتُه إليك؛ فإنه ليس عليك إلا الإنذار بما أُوحي إليك. والله على كل شيء حفيظ يدبِّر جميع شؤون خلقه."},{"id":"1486","jozz":"12","page":"223","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"1","line_end":"2","aya_no":"13","aya_text":"أَمۡ يَقُولُونَ ٱفۡتَرَىٰهُۖ قُلۡ فَأۡتُواْ بِعَشۡرِ سُوَرٖ مِّثۡلِهِۦ مُفۡتَرَيَٰتٖ وَٱدۡعُواْ مَنِ ٱسۡتَطَعۡتُم مِّن دُونِ ٱللَّهِ إِن كُنتُمۡ صَٰدِقِينَ","aya_text_emlaey":"أم يقولون افتراه قل فأتوا بعشر سور مثله مفتريات وادعوا من استطعتم من دون الله إن كنتم صادقين","aya_tafseer":"[13] بل أيقول هؤلاء المشركون من أهل «مكة»: إن محمداً قد افترى هذا القرآن؟ قل لهم: إن كان الأمر كما تزعمون فأتوا بعشر سور مثله مفتريات، وادعوا مَن استطعتم مِن جميع خلق الله ليساعدوكم على الإتيان بهذه السور العشر، إن كنتم صادقين في دعواكم."},{"id":"1487","jozz":"12","page":"223","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"3","line_end":"4","aya_no":"14","aya_text":"فَإِلَّمۡ يَسۡتَجِيبُواْ لَكُمۡ فَٱعۡلَمُوٓاْ أَنَّمَآ أُنزِلَ بِعِلۡمِ ٱللَّهِ وَأَن لَّآ إِلَٰهَ إِلَّا هُوَۖ فَهَلۡ أَنتُم مُّسۡلِمُونَ","aya_text_emlaey":"فإلم يستجيبوا لكم فاعلموا أنما أنـزل بعلم الله وأن لا إله إلا هو فهل أنتم مسلمون","aya_tafseer":"[14] فإن لم يستجب هؤلاء المشركون لكم -أيها الرسول- ومَن آمن معك- لما تدعونهم إليه؛ لِعَجْز الجميع عن ذلك، فاعلموا أن هذا القرآن إنما أنزله الله على رسوله بعلمه وليس من قول البشر، واعلموا أن لا إله يُعبد بحق إلا الله، فهل أنتم -بعد قيام هذه الحجة عليكم- مسلمون منقادون لله ورسوله؟"},{"id":"1488","jozz":"12","page":"223","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"4","line_end":"6","aya_no":"15","aya_text":"مَن كَانَ يُرِيدُ ٱلۡحَيَوٰةَ ٱلدُّنۡيَا وَزِينَتَهَا نُوَفِّ إِلَيۡهِمۡ أَعۡمَٰلَهُمۡ فِيهَا وَهُمۡ فِيهَا لَا يُبۡخَسُونَ","aya_text_emlaey":"من كان يريد الحياة الدنيا وزينتها نوف إليهم أعمالهم فيها وهم فيها لا يبخسون","aya_tafseer":"[15] من كان يريد بعمله الحياةَ الدنيا ومُتَعها نُعطهم ما قُسِم لهم من ثواب أعمالهم في الحياة الدنيا كاملاً غير منقوص."},{"id":"1489","jozz":"12","page":"223","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"6","line_end":"7","aya_no":"16","aya_text":"أُوْلَٰٓئِكَ ٱلَّذِينَ لَيۡسَ لَهُمۡ فِي ٱلۡأٓخِرَةِ إِلَّا ٱلنَّارُۖ وَحَبِطَ مَا صَنَعُواْ فِيهَا وَبَٰطِلٞ مَّا كَانُواْ يَعۡمَلُونَ","aya_text_emlaey":"أولئك الذين ليس لهم في الآخرة إلا النار وحبط ما صنعوا فيها وباطل ما كانوا يعملون","aya_tafseer":"[16] أولئك ليس لهم في الآخرة إلا نار جهنم يقاسون حرَّها، وذهب عنهم نَفْع ما عملوه، وكان عملهم باطلاً؛ لأنه لم يكن لوجه الله."},{"id":"1490","jozz":"12","page":"223","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"8","line_end":"11","aya_no":"17","aya_text":"أَفَمَن كَانَ عَلَىٰ بَيِّنَةٖ مِّن رَّبِّهِۦ وَيَتۡلُوهُ شَاهِدٞ مِّنۡهُ وَمِن قَبۡلِهِۦ كِتَٰبُ مُوسَىٰٓ إِمَامٗا وَرَحۡمَةًۚ أُوْلَٰٓئِكَ يُؤۡمِنُونَ بِهِۦۚ وَمَن يَكۡفُرۡ بِهِۦ مِنَ ٱلۡأَحۡزَابِ فَٱلنَّارُ مَوۡعِدُهُۥۚ فَلَا تَكُ فِي مِرۡيَةٖ مِّنۡهُۚ إِنَّهُ ٱلۡحَقُّ مِن رَّبِّكَ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يُؤۡمِنُونَ","aya_text_emlaey":"أفمن كان على بينة من ربه ويتلوه شاهد منه ومن قبله كتاب موسى إماما ورحمة أولئك يؤمنون به ومن يكفر به من الأحزاب فالنار موعده فلا تك في مرية منه إنه الحق من ربك ولكن أكثر الناس لا يؤمنون","aya_tafseer":"[17] أفمَن كان على حجة وبصيرة من ربه فيما يؤمن به، ويدعو إليه بالوحي الذي أنزل الله فيه هذه البينة، ويتلوها برهان آخرُ يشهد على كونه من عند الله، وهو جبريل أو محمد عليهما السلام، ويؤيد ذلك برهان ثالث من قَبْل القرآن، وهو التوراة -الكتاب الذي أُنزل على موسى إماماً ورحمة لمن آمن به-، كمن كان همه الحياة الفانية بزينتها؟ أولئك يصدِّقون بهذا القرآن ويعملون بأحكامه، ومن يكفر بهذا القرآن من الذين تحزَّبوا على رسول الله -صلى الله عليه وسلم- فجزاؤه النار، يَرِدُها لا محالة، فلا تك -أيها الرسول- في شك من أمر القرآن وكونِه من عند الله تعالى، بعد ما شهدت بذلك الأدلة والحجج، واعلم أن هذا الدين هو الحق من ربك، ولكن أكثر الناس لا يصدِّقون ولا يعملون بما أُمروا به. وهذا توجيه عام لأمة محمد -صلى الله عليه وسلم-."},{"id":"1491","jozz":"12","page":"223","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"11","line_end":"14","aya_no":"18","aya_text":"وَمَنۡ أَظۡلَمُ مِمَّنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبًاۚ أُوْلَٰٓئِكَ يُعۡرَضُونَ عَلَىٰ رَبِّهِمۡ وَيَقُولُ ٱلۡأَشۡهَٰدُ هَٰٓؤُلَآءِ ٱلَّذِينَ كَذَبُواْ عَلَىٰ رَبِّهِمۡۚ أَلَا لَعۡنَةُ ٱللَّهِ عَلَى ٱلظَّٰلِمِينَ","aya_text_emlaey":"ومن أظلم ممن افترى على الله كذبا أولئك يعرضون على ربهم ويقول الأشهاد هؤلاء الذين كذبوا على ربهم ألا لعنة الله على الظالمين","aya_tafseer":"[18] ولا أحد أظلم ممن اختلق على الله كذباً، أولئك سيعرضون على ربهم يوم القيامة؛ ليحاسبهم على أعمالهم. ويقولُ الأشهاد من الملائكة والنبيين وغيرهم: هؤلاء الذين كذَبوا على ربهم في الدنيا، قد سخط الله عليهم، ولعنهم لعنة لا تنقطع؛ لأن الظلم الذي اقترفوه صار وصفاً ملازماً لهم."},{"id":"1492","jozz":"12","page":"223","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"14","line_end":"15","aya_no":"19","aya_text":"ٱلَّذِينَ يَصُدُّونَ عَن سَبِيلِ ٱللَّهِ وَيَبۡغُونَهَا عِوَجٗا وَهُم بِٱلۡأٓخِرَةِ هُمۡ كَٰفِرُونَ","aya_text_emlaey":"الذين يصدون عن سبيل الله ويبغونها عوجا وهم بالآخرة هم كافرون","aya_tafseer":"[19] هؤلاء الظالمون الذين يمنعون الناس عن سبيل الله الموصلة إلى عبادته، ويريدون أن تكون هذه السبيل عوجاء بموافقتها لأهوائهم، وهم كافرون بالآخرة لا يؤمنون ببعث ولا جزاء."},{"id":"1493","jozz":"12","page":"224","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"1","line_end":"3","aya_no":"20","aya_text":"أُوْلَٰٓئِكَ لَمۡ يَكُونُواْ مُعۡجِزِينَ فِي ٱلۡأَرۡضِ وَمَا كَانَ لَهُم مِّن دُونِ ٱللَّهِ مِنۡ أَوۡلِيَآءَۘ يُضَٰعَفُ لَهُمُ ٱلۡعَذَابُۚ مَا كَانُواْ يَسۡتَطِيعُونَ ٱلسَّمۡعَ وَمَا كَانُواْ يُبۡصِرُونَ","aya_text_emlaey":"أولئك لم يكونوا معجزين في الأرض وما كان لهم من دون الله من أولياء يضاعف لهم العذاب ما كانوا يستطيعون السمع وما كانوا يبصرون","aya_tafseer":"[20] أولئك الكافرون لم يكونوا ليفوتوا الله في الدنيا هرباً، وما كان لهم مِن أنصار يمنعونهم من عقابه. يضاعَفُ لهم العذاب في جهنم؛ لأنهم كانوا لا يستطيعون أن يسمعوا القرآن سماع منتفع، أو يبصروا آيات الله في هذا الكون إبصار مهتد؛ لاشتغالهم بالكفر الذي كانوا عليه مقيمين."},{"id":"1494","jozz":"12","page":"224","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"3","line_end":"4","aya_no":"21","aya_text":"أُوْلَٰٓئِكَ ٱلَّذِينَ خَسِرُوٓاْ أَنفُسَهُمۡ وَضَلَّ عَنۡهُم مَّا كَانُواْ يَفۡتَرُونَ","aya_text_emlaey":"أولئك الذين خسروا أنفسهم وضل عنهم ما كانوا يفترون","aya_tafseer":"[21] أولئك الذين خسروا أنفسهم بافترائهم على الله، وذهب عنهم ما كانوا يفترون من الآلهة التي يدَّعون أنها تشفع لهم."},{"id":"1495","jozz":"12","page":"224","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"4","line_end":"5","aya_no":"22","aya_text":"لَا جَرَمَ أَنَّهُمۡ فِي ٱلۡأٓخِرَةِ هُمُ ٱلۡأَخۡسَرُونَ","aya_text_emlaey":"لا جرم أنهم في الآخرة هم الأخسرون","aya_tafseer":"[22] حقّاً أنهم في الآخرة أخسر الناس صفقة؛ لأنهم استبدلوا الدركاتِ بالدرجات، فكانوا في جهنم، وذلك هو الخسران المبين."},{"id":"1496","jozz":"12","page":"224","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"5","line_end":"7","aya_no":"23","aya_text":"إِنَّ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ وَأَخۡبَتُوٓاْ إِلَىٰ رَبِّهِمۡ أُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلۡجَنَّةِۖ هُمۡ فِيهَا خَٰلِدُونَ","aya_text_emlaey":"إن الذين آمنوا وعملوا الصالحات وأخبتوا إلى ربهم أولئك أصحاب الجنة هم فيها خالدون","aya_tafseer":"[23] إن الذين صدَّقوا الله ورسوله وعملوا الأعمال الصالحة، وخضعوا لله في كل ما أُمروا به ونُهوا عنه، أولئك هم أهل الجنة، لا يموتون فيها، ولا يَخْرجون منها أبداً."},{"id":"1497","jozz":"12","page":"224","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"7","line_end":"8","aya_no":"24","aya_text":"۞ مَثَلُ ٱلۡفَرِيقَيۡنِ كَٱلۡأَعۡمَىٰ وَٱلۡأَصَمِّ وَٱلۡبَصِيرِ وَٱلسَّمِيعِۚ هَلۡ يَسۡتَوِيَانِ مَثَلًاۚ أَفَلَا تَذَكَّرُونَ","aya_text_emlaey":"مثل الفريقين كالأعمى والأصم والبصير والسميع هل يستويان مثلا أفلا تذكرون","aya_tafseer":"[24] مثل فريقَي الكفر والإيمان كمثل الأعمى الذي لا يرى والأصم الذي لا يسمع والبصير والسميع: ففريق الكفر لا يبصر الحق فيتبعه، ولا يسمع داعي الله فيهتدي به، أما فريق الإيمان فقد أبصر حجج الله وسمع داعي الله فأجابه، هل يستوي هذان الفريقان؟ أفلا تعتبرون وتتفكرون؟"},{"id":"1498","jozz":"12","page":"224","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"9","line_end":"9","aya_no":"25","aya_text":"وَلَقَدۡ أَرۡسَلۡنَا نُوحًا إِلَىٰ قَوۡمِهِۦٓ إِنِّي لَكُمۡ نَذِيرٞ مُّبِينٌ","aya_text_emlaey":"ولقد أرسلنا نوحا إلى قومه إني لكم نذير مبين","aya_tafseer":"[25] ولقد أرسلنا نوحاً إلى قومه فقال لهم: إني نذير لكم من عذاب الله، مبيِّن لكم ما أُرسلت به إليكم من أمر الله ونهيه."},{"id":"1499","jozz":"12","page":"224","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"10","line_end":"10","aya_no":"26","aya_text":"أَن لَّا تَعۡبُدُوٓاْ إِلَّا ٱللَّهَۖ إِنِّيٓ أَخَافُ عَلَيۡكُمۡ عَذَابَ يَوۡمٍ أَلِيمٖ","aya_text_emlaey":"أن لا تعبدوا إلا الله إني أخاف عليكم عذاب يوم أليم","aya_tafseer":"[26] آمركم ألا تعبدوا إلا الله، إني أخاف عليكم -إن لم تفردوا الله وحده بالعبادة- عذاب يوم موجع."},{"id":"1500","jozz":"12","page":"224","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"11","line_end":"13","aya_no":"27","aya_text":"فَقَالَ ٱلۡمَلَأُ ٱلَّذِينَ كَفَرُواْ مِن قَوۡمِهِۦ مَا نَرَىٰكَ إِلَّا بَشَرٗا مِّثۡلَنَا وَمَا نَرَىٰكَ ٱتَّبَعَكَ إِلَّا ٱلَّذِينَ هُمۡ أَرَاذِلُنَا بَادِيَ ٱلرَّأۡيِ وَمَا نَرَىٰ لَكُمۡ عَلَيۡنَا مِن فَضۡلِۭ بَلۡ نَظُنُّكُمۡ كَٰذِبِينَ","aya_text_emlaey":"فقال الملأ الذين كفروا من قومه ما نراك إلا بشرا مثلنا وما نراك اتبعك إلا الذين هم أراذلنا بادي الرأي وما نرى لكم علينا من فضل بل نظنكم كاذبين","aya_tafseer":"[27] فقال رؤساء الكفر من قومه: إنك لست بمَلَك ولكنك بشر، فكيف أُوحي إليك مِن دوننا؟ وما نراك اتبعك إلا الذين هم أسافلنا وإنما اتبعوك من غير تفكر ولا رويَّة، وما نرى لكم علينا من فضل في رزق ولا مال لمَّا دخلتم في دينكم هذا، بل نعتقد أنكم كاذبون فيما تدَّعون."},{"id":"1501","jozz":"12","page":"224","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"14","line_end":"15","aya_no":"28","aya_text":"قَالَ يَٰقَوۡمِ أَرَءَيۡتُمۡ إِن كُنتُ عَلَىٰ بَيِّنَةٖ مِّن رَّبِّي وَءَاتَىٰنِي رَحۡمَةٗ مِّنۡ عِندِهِۦ فَعُمِّيَتۡ عَلَيۡكُمۡ أَنُلۡزِمُكُمُوهَا وَأَنتُمۡ لَهَا كَٰرِهُونَ","aya_text_emlaey":"قال ياقوم أرأيتم إن كنت على بينة من ربي وآتاني رحمة من عنده فعميت عليكم أنلزمكموها وأنتم لها كارهون","aya_tafseer":"[28] قال نوح: يا قومي أرأيتم إن كنتُ على حجة ظاهرة من ربي فيما جئتكم به تبيِّن لكم أنني على الحق من عنده، وآتاني رحمة من عنده، وهي النبوة والرسالة فأخفاها عليكم بسبب جهلكم وغروركم، فهل يصح أن نُلْزمكم إياها بالإكراه وأنتم جاحدون بها؟ لا نفعل ذلك، ولكن نَكِل أمركم إلى الله حتى يقضي في أمركم ما يشاء."},{"id":"1502","jozz":"12","page":"225","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"1","line_end":"3","aya_no":"29","aya_text":"وَيَٰقَوۡمِ لَآ أَسۡـَٔلُكُمۡ عَلَيۡهِ مَالًاۖ إِنۡ أَجۡرِيَ إِلَّا عَلَى ٱللَّهِۚ وَمَآ أَنَا۠ بِطَارِدِ ٱلَّذِينَ ءَامَنُوٓاْۚ إِنَّهُم مُّلَٰقُواْ رَبِّهِمۡ وَلَٰكِنِّيٓ أَرَىٰكُمۡ قَوۡمٗا تَجۡهَلُونَ","aya_text_emlaey":"وياقوم لا أسألكم عليه مالا إن أجري إلا على الله وما أنا بطارد الذين آمنوا إنهم ملاقو ربهم ولكني أراكم قوما تجهلون","aya_tafseer":"[29] قال نوح عليه السلام لقومه: يا قوم لا أسألكم على دعوتكم لتوحيد الله وإخلاص العبادة له مالاً تؤدونه إليَّ بعد إيمانكم، ولكن ثواب نصحي لكم على الله وحده، وليس من شأني أن أطرد المؤمنين، فإنهم ملاقو ربهم يوم القيامة، ولكني أراكم قوماً تجهلون؛ إذ تأمرونني بطرد أولياء الله وإبعادهم عني."},{"id":"1503","jozz":"12","page":"225","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"3","line_end":"4","aya_no":"30","aya_text":"وَيَٰقَوۡمِ مَن يَنصُرُنِي مِنَ ٱللَّهِ إِن طَرَدتُّهُمۡۚ أَفَلَا تَذَكَّرُونَ","aya_text_emlaey":"وياقوم من ينصرني من الله إن طردتهم أفلا تذكرون","aya_tafseer":"[30] ويا قوم مَن يمنعني من الله إن عاقبني على طردي المؤمنين؟ أفلا تتدبرون الأمور فتعلموا ما هو الأنفع لكم والأصلح؟"},{"id":"1504","jozz":"12","page":"225","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"4","line_end":"7","aya_no":"31","aya_text":"وَلَآ أَقُولُ لَكُمۡ عِندِي خَزَآئِنُ ٱللَّهِ وَلَآ أَعۡلَمُ ٱلۡغَيۡبَ وَلَآ أَقُولُ إِنِّي مَلَكٞ وَلَآ أَقُولُ لِلَّذِينَ تَزۡدَرِيٓ أَعۡيُنُكُمۡ لَن يُؤۡتِيَهُمُ ٱللَّهُ خَيۡرًاۖ ٱللَّهُ أَعۡلَمُ بِمَا فِيٓ أَنفُسِهِمۡ إِنِّيٓ إِذٗا لَّمِنَ ٱلظَّٰلِمِينَ","aya_text_emlaey":"ولا أقول لكم عندي خزائن الله ولا أعلم الغيب ولا أقول إني ملك ولا أقول للذين تزدري أعينكم لن يؤتيهم الله خيرا الله أعلم بما في أنفسهم إني إذا لمن الظالمين","aya_tafseer":"[31] ولا أقول لكم: إني أملك التصرف في خزائن الله، ولا أعلم الغيب، ولستُ بمَلَك من الملائكة، ولا أقول لهؤلاء الذين تحتقرون من ضعفاء المؤمنين: لن يؤتيكم الله ثواباً على أعمالكم، فالله وحده أعلم بما في صدورهم وقلوبهم، ولئن فعلتُ ذلك إني إذاً لمن الظالمين لأنفسهم ولغيرهم."},{"id":"1505","jozz":"12","page":"225","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"7","line_end":"8","aya_no":"32","aya_text":"قَالُواْ يَٰنُوحُ قَدۡ جَٰدَلۡتَنَا فَأَكۡثَرۡتَ جِدَٰلَنَا فَأۡتِنَا بِمَا تَعِدُنَآ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ","aya_text_emlaey":"قالوا يانوح قد جادلتنا فأكثرت جدالنا فأتنا بما تعدنا إن كنت من الصادقين","aya_tafseer":"[32] قالوا: يا نوح قد حاججتنا فأكثرت جدالنا، فأتنا بما تعدنا من العذاب إن كنت من الصادقين في دعواك."},{"id":"1506","jozz":"12","page":"225","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"8","line_end":"9","aya_no":"33","aya_text":"قَالَ إِنَّمَا يَأۡتِيكُم بِهِ ٱللَّهُ إِن شَآءَ وَمَآ أَنتُم بِمُعۡجِزِينَ","aya_text_emlaey":"قال إنما يأتيكم به الله إن شاء وما أنتم بمعجزين","aya_tafseer":"[33] قال نوح لقومه: إن الله وحده هو الذي يأتيكم بالعذاب إذا شاء، ولستم بفائتيه إذا أراد أن يعذبكم؛ لأنه سبحانه لا يعجزه شيء في الأرض ولا في السماء."},{"id":"1507","jozz":"12","page":"225","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"9","line_end":"11","aya_no":"34","aya_text":"وَلَا يَنفَعُكُمۡ نُصۡحِيٓ إِنۡ أَرَدتُّ أَنۡ أَنصَحَ لَكُمۡ إِن كَانَ ٱللَّهُ يُرِيدُ أَن يُغۡوِيَكُمۡۚ هُوَ رَبُّكُمۡ وَإِلَيۡهِ تُرۡجَعُونَ","aya_text_emlaey":"ولا ينفعكم نصحي إن أردت أن أنصح لكم إن كان الله يريد أن يغويكم هو ربكم وإليه ترجعون","aya_tafseer":"[34] ولا ينفعكم نصحي واجتهادي في دعوتكم للإيمان، إن كان الله يريد أن يضلَّكم ويهلككم، هو سبحانه مالككم، وإليه تُرجَعون في الآخرة للحساب والجزاء."},{"id":"1508","jozz":"12","page":"225","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"11","line_end":"12","aya_no":"35","aya_text":"أَمۡ يَقُولُونَ ٱفۡتَرَىٰهُۖ قُلۡ إِنِ ٱفۡتَرَيۡتُهُۥ فَعَلَيَّ إِجۡرَامِي وَأَنَا۠ بَرِيٓءٞ مِّمَّا تُجۡرِمُونَ","aya_text_emlaey":"أم يقولون افتراه قل إن افتريته فعلي إجرامي وأنا بريء مما تجرمون","aya_tafseer":"[35] بل أيقول هؤلاء المشركون من قوم نوح: افترى نوح هذا القول؟ قل لهم: إن كنتُ قد افتريتُ ذلك على الله فعليَّ وحدي إثم ذلك، وإذا كنتُ صادقاً فأنتم المجرمون الآثمون، وأنا بريء مِن كفركم وتكذيبكم وإجرامكم."},{"id":"1509","jozz":"12","page":"225","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"13","line_end":"14","aya_no":"36","aya_text":"وَأُوحِيَ إِلَىٰ نُوحٍ أَنَّهُۥ لَن يُؤۡمِنَ مِن قَوۡمِكَ إِلَّا مَن قَدۡ ءَامَنَ فَلَا تَبۡتَئِسۡ بِمَا كَانُواْ يَفۡعَلُونَ","aya_text_emlaey":"وأوحي إلى نوح أنه لن يؤمن من قومك إلا من قد آمن فلا تبتئس بما كانوا يفعلون","aya_tafseer":"[36] وأوحى الله سبحانه وتعالى إلى نوح -عليه السلام- لمَّا حق على قومه العذاب، أنه لن يؤمن بالله إلا مَن قد آمن مِن قبل، فلا تحزن يا نوح على ما كانوا يفعلون."},{"id":"1510","jozz":"12","page":"225","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"14","line_end":"15","aya_no":"37","aya_text":"وَٱصۡنَعِ ٱلۡفُلۡكَ بِأَعۡيُنِنَا وَوَحۡيِنَا وَلَا تُخَٰطِبۡنِي فِي ٱلَّذِينَ ظَلَمُوٓاْ إِنَّهُم مُّغۡرَقُونَ","aya_text_emlaey":"واصنع الفلك بأعيننا ووحينا ولا تخاطبني في الذين ظلموا إنهم مغرقون","aya_tafseer":"[37] واصنع السفينة بمرأى منَّا وبأمرنا لك ومعونتنا، وأنت في حفظنا وكِلاءتنا، ولا تطلب مني إمهال هؤلاء الذين ظلموا أنفسهم من قومك بكفرهم، فإنهم مغرقون بالطوفان. وفي الآية إثبات صفة العين لله تعالى على ما يليق به سبحانه."},{"id":"1511","jozz":"12","page":"226","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"1","line_end":"2","aya_no":"38","aya_text":"وَيَصۡنَعُ ٱلۡفُلۡكَ وَكُلَّمَا مَرَّ عَلَيۡهِ مَلَأٞ مِّن قَوۡمِهِۦ سَخِرُواْ مِنۡهُۚ قَالَ إِن تَسۡخَرُواْ مِنَّا فَإِنَّا نَسۡخَرُ مِنكُمۡ كَمَا تَسۡخَرُونَ","aya_text_emlaey":"ويصنع الفلك وكلما مر عليه ملأ من قومه سخروا منه قال إن تسخروا منا فإنا نسخر منكم كما تسخرون","aya_tafseer":"[38] ويصنع نوح السفينة، وكلَّما مر عليه جماعة من كبراء قومه سخروا منه، قال لهم نوح: إن تسخروا منا اليوم لجهلكم بصدق وعد الله، فإنا نسخر منكم غداً عند الغرق كما تسخرون منا."},{"id":"1512","jozz":"12","page":"226","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"3","line_end":"4","aya_no":"39","aya_text":"فَسَوۡفَ تَعۡلَمُونَ مَن يَأۡتِيهِ عَذَابٞ يُخۡزِيهِ وَيَحِلُّ عَلَيۡهِ عَذَابٞ مُّقِيمٌ","aya_text_emlaey":"فسوف تعلمون من يأتيه عذاب يخزيه ويحل عليه عذاب مقيم","aya_tafseer":"[39] فسوف تعلمون إذا جاء أمر الله بذلك: من الذي يأتيه في الدنيا عذاب الله الذي يُهينه، وينزل به في الآخرة عذاب دائم لا انقطاع له؟"},{"id":"1513","jozz":"12","page":"226","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"4","line_end":"6","aya_no":"40","aya_text":"حَتَّىٰٓ إِذَا جَآءَ أَمۡرُنَا وَفَارَ ٱلتَّنُّورُ قُلۡنَا ٱحۡمِلۡ فِيهَا مِن كُلّٖ زَوۡجَيۡنِ ٱثۡنَيۡنِ وَأَهۡلَكَ إِلَّا مَن سَبَقَ عَلَيۡهِ ٱلۡقَوۡلُ وَمَنۡ ءَامَنَۚ وَمَآ ءَامَنَ مَعَهُۥٓ إِلَّا قَلِيلٞ","aya_text_emlaey":"حتى إذا جاء أمرنا وفار التنور قلنا احمل فيها من كل زوجين اثنين وأهلك إلا من سبق عليه القول ومن آمن وما آمن معه إلا قليل","aya_tafseer":"[40] حتى إذا جاء أمرنا بإهلاكهم كما وَعدْنا نوحاً بذلك، ونبع الماء بقوة من التنور -وهو المكان الذي يخبز فيه- علامة على مجيء العذاب، قلنا لنوح: احمل في السفينة من كل نوع من أنواع الحيوانات ذكراً وأنثى، واحمل فيها أهل بيتك، إلا مَن سبق عليهم القول ممن لم يؤمن بالله كابنه وامرأته، واحمل فيها من آمن معك من قومك، وما آمن معه إلا قليل مع طول المدة والمقام فيهم."},{"id":"1514","jozz":"12","page":"226","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"6","line_end":"7","aya_no":"41","aya_text":"۞ وَقَالَ ٱرۡكَبُواْ فِيهَا بِسۡمِ ٱللَّهِ مَجۡر۪ىٰهَا وَمُرۡسَىٰهَآۚ إِنَّ رَبِّي لَغَفُورٞ رَّحِيمٞ","aya_text_emlaey":"وقال اركبوا فيها بسم الله مجراها ومرساها إن ربي لغفور رحيم","aya_tafseer":"[41] وقال نوح لمن آمن معه: اركبوا في السفينة، باسم الله يكون جريها على وجه الماء، وباسم الله يكون منتهى سيرها ورُسوُّها. إن ربي لَغفور ذنوبَ من تاب وأناب إليه من عباده، رحيم بهم أن يعذبهم بعد التوبة."},{"id":"1515","jozz":"12","page":"226","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"8","line_end":"9","aya_no":"42","aya_text":"وَهِيَ تَجۡرِي بِهِمۡ فِي مَوۡجٖ كَٱلۡجِبَالِ وَنَادَىٰ نُوحٌ ٱبۡنَهُۥ وَكَانَ فِي مَعۡزِلٖ يَٰبُنَيَّ ٱرۡكَب مَّعَنَا وَلَا تَكُن مَّعَ ٱلۡكَٰفِرِينَ","aya_text_emlaey":"وهي تجري بهم في موج كالجبال ونادى نوح ابنه وكان في معزل يابني اركب معنا ولا تكن مع الكافرين","aya_tafseer":"[42] وهي تجري بهم في موج يعلو ويرتفع حتى يصير كالجبال في علوها، ونادى نوح ابنه -وكان في مكانٍ عَزَل فيه نفسه عن المؤمنين- فقال له: يا بني اركب معنا في السفينة، ولا تكن مع الكافرين بالله فتغرق."},{"id":"1516","jozz":"12","page":"226","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"10","line_end":"12","aya_no":"43","aya_text":"قَالَ سَـَٔاوِيٓ إِلَىٰ جَبَلٖ يَعۡصِمُنِي مِنَ ٱلۡمَآءِۚ قَالَ لَا عَاصِمَ ٱلۡيَوۡمَ مِنۡ أَمۡرِ ٱللَّهِ إِلَّا مَن رَّحِمَۚ وَحَالَ بَيۡنَهُمَا ٱلۡمَوۡجُ فَكَانَ مِنَ ٱلۡمُغۡرَقِينَ","aya_text_emlaey":"قال سآوي إلى جبل يعصمني من الماء قال لا عاصم اليوم من أمر الله إلا من رحم وحال بينهما الموج فكان من المغرقين","aya_tafseer":"[43] قال ابن نوح: سألجأ إلى جبل أتحصَّن به من الماء، فيمنعني من الغرق، فأجابه نوح: لا مانع اليوم من أمر الله وقضائه الذي قد نزل بالخلق من الغرق والهلاك إلا مَن رحمه الله تعالى، فآمِنْ واركب في السفينة معنا، وحال الموج المرتفع بين نوح وابنه، فكان من المغرقين الهالكين."},{"id":"1517","jozz":"12","page":"226","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"12","line_end":"14","aya_no":"44","aya_text":"وَقِيلَ يَٰٓأَرۡضُ ٱبۡلَعِي مَآءَكِ وَيَٰسَمَآءُ أَقۡلِعِي وَغِيضَ ٱلۡمَآءُ وَقُضِيَ ٱلۡأَمۡرُ وَٱسۡتَوَتۡ عَلَى ٱلۡجُودِيِّۖ وَقِيلَ بُعۡدٗا لِّلۡقَوۡمِ ٱلظَّٰلِمِينَ","aya_text_emlaey":"وقيل ياأرض ابلعي ماءك وياسماء أقلعي وغيض الماء وقضي الأمر واستوت على الجودي وقيل بعدا للقوم الظالمين","aya_tafseer":"[44] وقال الله للأرض- بعد هلاك قوم نوح-: يا أرض اشربي ماءك، ويا سماء أمسكي عن المطر، ونقص الماء ونَضَب، وقُضي أمر الله بهلاك قوم نوح، ورست السفينة على جبل الجوديِّ، وقيل: هلاكاً وبُعْداً للقوم الظالمين الذين تجاوزوا حدود الله، ولم يؤمنوا به."},{"id":"1518","jozz":"12","page":"226","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"14","line_end":"15","aya_no":"45","aya_text":"وَنَادَىٰ نُوحٞ رَّبَّهُۥ فَقَالَ رَبِّ إِنَّ ٱبۡنِي مِنۡ أَهۡلِي وَإِنَّ وَعۡدَكَ ٱلۡحَقُّ وَأَنتَ أَحۡكَمُ ٱلۡحَٰكِمِينَ","aya_text_emlaey":"ونادى نوح ربه فقال رب إن ابني من أهلي وإن وعدك الحق وأنت أحكم الحاكمين","aya_tafseer":"[45] ونادى نوح ربه فقال: رب إنك وعَدْتني أن تنجيني وأهلي من الغرق والهلاك، وإن ابني هذا من أهلي، وإن وعدك الحق الذي لا خُلْف فيه، وأنت أحكم الحاكمين وأعدلهم."},{"id":"1519","jozz":"12","page":"227","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"1","line_end":"2","aya_no":"46","aya_text":"قَالَ يَٰنُوحُ إِنَّهُۥ لَيۡسَ مِنۡ أَهۡلِكَۖ إِنَّهُۥ عَمَلٌ غَيۡرُ صَٰلِحٖۖ فَلَا تَسۡـَٔلۡنِ مَا لَيۡسَ لَكَ بِهِۦ عِلۡمٌۖ إِنِّيٓ أَعِظُكَ أَن تَكُونَ مِنَ ٱلۡجَٰهِلِينَ","aya_text_emlaey":"قال يانوح إنه ليس من أهلك إنه عمل غير صالح فلا تسألن ما ليس لك به علم إني أعظك أن تكون من الجاهلين","aya_tafseer":"[46] قال الله: يا نوح إن ابنك الذي هلك ليس من أهلك الذين وعدتك أن أنجيهم؛ وذلك بسبب كفره، وعملِه عملاً غير صالح، وإني أنهاك أن تسألني أمراً لا علم لك به، إني أعظك لئلا تكون من الجاهلين في مسألتك إياي عن ذلك."},{"id":"1520","jozz":"12","page":"227","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"3","line_end":"4","aya_no":"47","aya_text":"قَالَ رَبِّ إِنِّيٓ أَعُوذُ بِكَ أَنۡ أَسۡـَٔلَكَ مَا لَيۡسَ لِي بِهِۦ عِلۡمٞۖ وَإِلَّا تَغۡفِرۡ لِي وَتَرۡحَمۡنِيٓ أَكُن مِّنَ ٱلۡخَٰسِرِينَ","aya_text_emlaey":"قال رب إني أعوذ بك أن أسألك ما ليس لي به علم وإلا تغفر لي وترحمني أكن من الخاسرين","aya_tafseer":"[47] قال نوح: يا رب إني أعتصم وأستجير بك أن أسألك ما ليس لي به علم، وإن لم تغفر لي ذنبي، وترحمني برحمتك، أكن من الذين غَبَنوا أنفسهم حظوظها وهلكوا."},{"id":"1521","jozz":"12","page":"227","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"4","line_end":"6","aya_no":"48","aya_text":"قِيلَ يَٰنُوحُ ٱهۡبِطۡ بِسَلَٰمٖ مِّنَّا وَبَرَكَٰتٍ عَلَيۡكَ وَعَلَىٰٓ أُمَمٖ مِّمَّن مَّعَكَۚ وَأُمَمٞ سَنُمَتِّعُهُمۡ ثُمَّ يَمَسُّهُم مِّنَّا عَذَابٌ أَلِيمٞ","aya_text_emlaey":"قيل يانوح اهبط بسلام منا وبركات عليك وعلى أمم ممن معك وأمم سنمتعهم ثم يمسهم منا عذاب أليم","aya_tafseer":"[48] قال الله: يا نوح اهبط من السفينة إلى الأرض بأمن وسلامة منَّا وخيراتٍ ونعمٍ دائمة عليك وعلى أمم ممن معك. وهناك أمم وجماعات من أهل الشقاء سنمتعهم في الحياة الدنيا، إلى أن يبلغوا آجالهم، ثم ينالهم منا العذاب الموجع يوم القيامة."},{"id":"1522","jozz":"12","page":"227","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"6","line_end":"8","aya_no":"49","aya_text":"تِلۡكَ مِنۡ أَنۢبَآءِ ٱلۡغَيۡبِ نُوحِيهَآ إِلَيۡكَۖ مَا كُنتَ تَعۡلَمُهَآ أَنتَ وَلَا قَوۡمُكَ مِن قَبۡلِ هَٰذَاۖ فَٱصۡبِرۡۖ إِنَّ ٱلۡعَٰقِبَةَ لِلۡمُتَّقِينَ","aya_text_emlaey":"تلك من أنباء الغيب نوحيها إليك ما كنت تعلمها أنت ولا قومك من قبل هذا فاصبر إن العاقبة للمتقين","aya_tafseer":"[49] تلك القصة التي قصصناها عليك -أيها الرسول- عن نوح وقومه هي من أخبار الغيب السالفة، نوحيها إليك، ما كنت تعلمها أنت ولا قومك مِن قبل هذا البيان، فاصبر على تكذيب قومك وإيذائهم لك، كما صبر الأنبياء من قبل، إن العاقبة الطيبة في الدنيا والآخرة للمتقين الذين يخشون الله."},{"id":"1523","jozz":"12","page":"227","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"9","line_end":"10","aya_no":"50","aya_text":"وَإِلَىٰ عَادٍ أَخَاهُمۡ هُودٗاۚ قَالَ يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥٓۖ إِنۡ أَنتُمۡ إِلَّا مُفۡتَرُونَ","aya_text_emlaey":"وإلى عاد أخاهم هودا قال ياقوم اعبدوا الله ما لكم من إله غيره إن أنتم إلا مفترون","aya_tafseer":"[50] وأرسلنا إلى عاد أخاهم هوداً، قال لهم: يا قوم اعبدوا الله وحده، ليس لكم من إله يستحق العبادة غيره جلَّ وعلا، فأخلِصوا له العبادة، فما أنتم إلا كاذبون في إشراككم بالله."},{"id":"1524","jozz":"12","page":"227","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"10","line_end":"11","aya_no":"51","aya_text":"يَٰقَوۡمِ لَآ أَسۡـَٔلُكُمۡ عَلَيۡهِ أَجۡرًاۖ إِنۡ أَجۡرِيَ إِلَّا عَلَى ٱلَّذِي فَطَرَنِيٓۚ أَفَلَا تَعۡقِلُونَ","aya_text_emlaey":"ياقوم لا أسألكم عليه أجرا إن أجري إلا على الذي فطرني أفلا تعقلون","aya_tafseer":"[51] يا قوم لا أسألكم على ما أدعوكم إليه من إخلاص العبادة لله وترك عبادة الأوثان أجراً، ما أجري على دعوتي لكم إلا على الله الذي خلقني، أفلا تعقلون فتميِّزوا بين الحق والباطل؟"},{"id":"1525","jozz":"12","page":"227","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"12","line_end":"14","aya_no":"52","aya_text":"وَيَٰقَوۡمِ ٱسۡتَغۡفِرُواْ رَبَّكُمۡ ثُمَّ تُوبُوٓاْ إِلَيۡهِ يُرۡسِلِ ٱلسَّمَآءَ عَلَيۡكُم مِّدۡرَارٗا وَيَزِدۡكُمۡ قُوَّةً إِلَىٰ قُوَّتِكُمۡ وَلَا تَتَوَلَّوۡاْ مُجۡرِمِينَ","aya_text_emlaey":"وياقوم استغفروا ربكم ثم توبوا إليه يرسل السماء عليكم مدرارا ويزدكم قوة إلى قوتكم ولا تتولوا مجرمين","aya_tafseer":"[52] ويا قوم اطلبوا مغفرة الله بالإيمان به، ثم توبوا إليه من ذنوبكم، فإنكم إن فعلتم ذلك يرسل المطر عليكم متتابعاً كثيراً، فتكثر خيراتكم، ويزدكم قوة إلى قوتكم بكثرة ذرياتكم وتتابع النِّعم عليكم، ولا تُعرضوا عما دعوتكم إليه مصرِّين على إجرامكم."},{"id":"1526","jozz":"12","page":"227","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"14","line_end":"15","aya_no":"53","aya_text":"قَالُواْ يَٰهُودُ مَا جِئۡتَنَا بِبَيِّنَةٖ وَمَا نَحۡنُ بِتَارِكِيٓ ءَالِهَتِنَا عَن قَوۡلِكَ وَمَا نَحۡنُ لَكَ بِمُؤۡمِنِينَ","aya_text_emlaey":"قالوا ياهود ما جئتنا ببينة وما نحن بتاركي آلهتنا عن قولك وما نحن لك بمؤمنين","aya_tafseer":"[53] قالوا: يا هود ما جئتنا بحجة واضحة على صحة ما تدعونا إليه، وما نحن بتاركي آلهتنا التي نعبدها من أجل قولك، وما نحن بمصدِّقين لك فيما تدَّعيه."},{"id":"1527","jozz":"12","page":"228","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"1","line_end":"2","aya_no":"54","aya_text":"إِن نَّقُولُ إِلَّا ٱعۡتَرَىٰكَ بَعۡضُ ءَالِهَتِنَا بِسُوٓءٖۗ قَالَ إِنِّيٓ أُشۡهِدُ ٱللَّهَ وَٱشۡهَدُوٓاْ أَنِّي بَرِيٓءٞ مِّمَّا تُشۡرِكُونَ","aya_text_emlaey":"إن نقول إلا اعتراك بعض آلهتنا بسوء قال إني أشهد الله واشهدوا أني بريء مما تشركون","aya_tafseer":"[54] ما نقول إلا أن بعض آلهتنا أصابك بجنون بسبب نهيك عن عبادتها. قال لهم: إني أُشهد الله على ما أقول، وأُشهدكم على أنني بريء مما تشركون."},{"id":"1528","jozz":"12","page":"228","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"2","line_end":"3","aya_no":"55","aya_text":"مِن دُونِهِۦۖ فَكِيدُونِي جَمِيعٗا ثُمَّ لَا تُنظِرُونِ","aya_text_emlaey":"من دونه فكيدوني جميعا ثم لا تنظرون","aya_tafseer":"[55]، مِن دون الله من الأنداد والأصنام، فانظروا واجتهدوا أنتم ومَن زعمتم من آلهتكم في إلحاق الضرر بي، ثم لا تؤخروا ذلك طرفة عين؛ ذلك أن هوداً واثق كلَّ الوثوق أنه لا يصيبه منهم ولا من آلهتهم أذى."},{"id":"1529","jozz":"12","page":"228","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"3","line_end":"4","aya_no":"56","aya_text":"إِنِّي تَوَكَّلۡتُ عَلَى ٱللَّهِ رَبِّي وَرَبِّكُمۚ مَّا مِن دَآبَّةٍ إِلَّا هُوَ ءَاخِذُۢ بِنَاصِيَتِهَآۚ إِنَّ رَبِّي عَلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ","aya_text_emlaey":"إني توكلت على الله ربي وربكم ما من دابة إلا هو آخذ بناصيتها إن ربي على صراط مستقيم","aya_tafseer":"[56] إني توكلت على الله ربي وربكم مالكِ كل شيء والمتصرف فيه، فلا يصيبني شيء إلا بأمره، وهو القادر على كل شيء، فليس من شيء يدِبُّ على هذه الأرض إلا والله مالكه، وهو في سلطانه وتصرفه. إن ربي على صراط مستقيم، أي عدل في قضائه وشرعه وأمره. يجازي المحسن بإحسانه والمسيء بإساءته."},{"id":"1530","jozz":"12","page":"228","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"5","line_end":"6","aya_no":"57","aya_text":"فَإِن تَوَلَّوۡاْ فَقَدۡ أَبۡلَغۡتُكُم مَّآ أُرۡسِلۡتُ بِهِۦٓ إِلَيۡكُمۡۚ وَيَسۡتَخۡلِفُ رَبِّي قَوۡمًا غَيۡرَكُمۡ وَلَا تَضُرُّونَهُۥ شَيۡـًٔاۚ إِنَّ رَبِّي عَلَىٰ كُلِّ شَيۡءٍ حَفِيظٞ","aya_text_emlaey":"فإن تولوا فقد أبلغتكم ما أرسلت به إليكم ويستخلف ربي قوما غيركم ولا تضرونه شيئا إن ربي على كل شيء حفيظ","aya_tafseer":"[57] فإن تُعرضوا عما أدعوكم إليه من توحيد الله وإخلاص العبادة له فقد أبلغتكم رسالة ربي إليكم، وقامت عليكم الحجة، وحيث لم تؤمنوا بالله فسيهلككم ويأتي بقوم آخرين يخلفونكم في دياركم وأموالكم، ويخلصون لله العبادة، ولا تضرونه شيئاً، إن ربي على كل شيء حفيظ، فهو الذي يحفظني من أن تنالوني بسوء."},{"id":"1531","jozz":"12","page":"228","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"7","line_end":"8","aya_no":"58","aya_text":"وَلَمَّا جَآءَ أَمۡرُنَا نَجَّيۡنَا هُودٗا وَٱلَّذِينَ ءَامَنُواْ مَعَهُۥ بِرَحۡمَةٖ مِّنَّا وَنَجَّيۡنَٰهُم مِّنۡ عَذَابٍ غَلِيظٖ","aya_text_emlaey":"ولما جاء أمرنا نجينا هودا والذين آمنوا معه برحمة منا ونجيناهم من عذاب غليظ","aya_tafseer":"[58] ولما جاء أمرنا بعذاب قوم هود نجَّينا منه هوداً والمؤمنين بفضل منَّا عليهم ورحمة، ونجَّيناهم من عذاب شديد أحلَّه الله بعادٍ فأصبحوا لا يُرى إلا مساكنُهم."},{"id":"1532","jozz":"12","page":"228","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"8","line_end":"9","aya_no":"59","aya_text":"وَتِلۡكَ عَادٞۖ جَحَدُواْ بِـَٔايَٰتِ رَبِّهِمۡ وَعَصَوۡاْ رُسُلَهُۥ وَٱتَّبَعُوٓاْ أَمۡرَ كُلِّ جَبَّارٍ عَنِيدٖ","aya_text_emlaey":"وتلك عاد جحدوا بآيات ربهم وعصوا رسله واتبعوا أمر كل جبار عنيد","aya_tafseer":"[59] وتلك عاد كفروا بآيات الله وعصَوا رسله، وأطاعوا أمر كل مستكبر على الله لا يقبل الحق ولا يُذْعن له."},{"id":"1533","jozz":"12","page":"228","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"9","line_end":"11","aya_no":"60","aya_text":"وَأُتۡبِعُواْ فِي هَٰذِهِ ٱلدُّنۡيَا لَعۡنَةٗ وَيَوۡمَ ٱلۡقِيَٰمَةِۗ أَلَآ إِنَّ عَادٗا كَفَرُواْ رَبَّهُمۡۗ أَلَا بُعۡدٗا لِّعَادٖ قَوۡمِ هُودٖ","aya_text_emlaey":"وأتبعوا في هذه الدنيا لعنة ويوم القيامة ألا إن عادا كفروا ربهم ألا بعدا لعاد قوم هود","aya_tafseer":"[60] وأُتبعوا في هذه الدنيا لعنة من الله وسخطاً منه يوم القيامة. ألا إن عاداً جحدوا ربهم وكذَّبوا رسله. ألا بُعْداً وهلاكاً لعاد قوم هود؛ بسبب شركهم وكفرهم نعمة ربهم."},{"id":"1534","jozz":"12","page":"228","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"11","line_end":"13","aya_no":"61","aya_text":"۞ وَإِلَىٰ ثَمُودَ أَخَاهُمۡ صَٰلِحٗاۚ قَالَ يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥۖ هُوَ أَنشَأَكُم مِّنَ ٱلۡأَرۡضِ وَٱسۡتَعۡمَرَكُمۡ فِيهَا فَٱسۡتَغۡفِرُوهُ ثُمَّ تُوبُوٓاْ إِلَيۡهِۚ إِنَّ رَبِّي قَرِيبٞ مُّجِيبٞ","aya_text_emlaey":"وإلى ثمود أخاهم صالحا قال ياقوم اعبدوا الله ما لكم من إله غيره هو أنشأكم من الأرض واستعمركم فيها فاستغفروه ثم توبوا إليه إن ربي قريب مجيب","aya_tafseer":"[61] وأرسلنا إلى ثمود أخاهم صالحاً، فقال لهم: يا قوم اعبدوا الله وحده ليس لكم من إله يستحق العبادة غيره جلَّ وعلا، فأخلصوا له العبادة، هو الذي بدأ خَلْقكم من الأرض بخلق أبيكم آدم منها، وجعلكم عُمَّاراً لها، فاسألوه أن يغفر لكم ذنوبكم، وارجعوا إليه بالتوبة النصوح. إن ربي قريب لمن أخلص له العبادة، ورغب إليه في التوبة، مجيب له إذا دعاه."},{"id":"1535","jozz":"12","page":"228","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"14","line_end":"15","aya_no":"62","aya_text":"قَالُواْ يَٰصَٰلِحُ قَدۡ كُنتَ فِينَا مَرۡجُوّٗا قَبۡلَ هَٰذَآۖ أَتَنۡهَىٰنَآ أَن نَّعۡبُدَ مَا يَعۡبُدُ ءَابَآؤُنَا وَإِنَّنَا لَفِي شَكّٖ مِّمَّا تَدۡعُونَآ إِلَيۡهِ مُرِيبٖ","aya_text_emlaey":"قالوا ياصالح قد كنت فينا مرجوا قبل هذا أتنهانا أن نعبد ما يعبد آباؤنا وإننا لفي شك مما تدعونا إليه مريب","aya_tafseer":"[62] قالت ثمود لنبيِّهم صالح: لقد كنا نرجو أن تكون فينا سيداً مطاعاً قبل هذا القول الذي قلته لنا، أتنهانا أن نعبد الآلهة التي كان يعبدها آباؤنا؟ وإننا لفي شكٍّ مريب مِن دعوتك لنا إلى عبادة الله وحده."},{"id":"1536","jozz":"12","page":"229","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"1","line_end":"3","aya_no":"63","aya_text":"قَالَ يَٰقَوۡمِ أَرَءَيۡتُمۡ إِن كُنتُ عَلَىٰ بَيِّنَةٖ مِّن رَّبِّي وَءَاتَىٰنِي مِنۡهُ رَحۡمَةٗ فَمَن يَنصُرُنِي مِنَ ٱللَّهِ إِنۡ عَصَيۡتُهُۥۖ فَمَا تَزِيدُونَنِي غَيۡرَ تَخۡسِيرٖ","aya_text_emlaey":"قال ياقوم أرأيتم إن كنت على بينة من ربي وآتاني منه رحمة فمن ينصرني من الله إن عصيته فما تزيدونني غير تخسير","aya_tafseer":"[63] قال صالح لقومه: يا قوم أخبروني إن كنت على برهان من الله وآتاني منه النبوة والحكمة، فمن الذي يدفع عني عقاب الله تعالى إن عصيته فلم أبلِّغ الرسالة وأنصحْ لكم؟ فما تزيدونني غير تضليل وإبعاد عن الخير."},{"id":"1537","jozz":"12","page":"229","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"3","line_end":"5","aya_no":"64","aya_text":"وَيَٰقَوۡمِ هَٰذِهِۦ نَاقَةُ ٱللَّهِ لَكُمۡ ءَايَةٗۖ فَذَرُوهَا تَأۡكُلۡ فِيٓ أَرۡضِ ٱللَّهِۖ وَلَا تَمَسُّوهَا بِسُوٓءٖ فَيَأۡخُذَكُمۡ عَذَابٞ قَرِيبٞ","aya_text_emlaey":"وياقوم هذه ناقة الله لكم آية فذروها تأكل في أرض الله ولا تمسوها بسوء فيأخذكم عذاب قريب","aya_tafseer":"[64] ويا قوم هذه ناقة الله جعلها لكم حجة وعلامة تدلُّ على صدقي فيما أدعوكم إليه، فاتركوها تأكل في أرض الله فليس عليكم رزقها، ولا تمسُّوها بعَقْر، فإنكم إن فعلتم ذلك يأخذكم من الله عذاب قريب من عَقْرها."},{"id":"1538","jozz":"12","page":"229","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"5","line_end":"6","aya_no":"65","aya_text":"فَعَقَرُوهَا فَقَالَ تَمَتَّعُواْ فِي دَارِكُمۡ ثَلَٰثَةَ أَيَّامٖۖ ذَٰلِكَ وَعۡدٌ غَيۡرُ مَكۡذُوبٖ","aya_text_emlaey":"فعقروها فقال تمتعوا في داركم ثلاثة أيام ذلك وعد غير مكذوب","aya_tafseer":"[65] فكذَّبوه ونحروا الناقة، فقال لهم صالح: استمتعوا بحياتكم في بلدكم ثلاثة أيام، فإن العذاب نازل بكم بعدها، وذلك وَعْدٌ من الله غير مكذوب، لابد من وقوعه."},{"id":"1539","jozz":"12","page":"229","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"6","line_end":"8","aya_no":"66","aya_text":"فَلَمَّا جَآءَ أَمۡرُنَا نَجَّيۡنَا صَٰلِحٗا وَٱلَّذِينَ ءَامَنُواْ مَعَهُۥ بِرَحۡمَةٖ مِّنَّا وَمِنۡ خِزۡيِ يَوۡمِئِذٍۚ إِنَّ رَبَّكَ هُوَ ٱلۡقَوِيُّ ٱلۡعَزِيزُ","aya_text_emlaey":"فلما جاء أمرنا نجينا صالحا والذين آمنوا معه برحمة منا ومن خزي يومئذ إن ربك هو القوي العزيز","aya_tafseer":"[66] فلما جاء أمرنا بهلاك ثمود نجينا صالحاً والذين آمنوا معه من الهلاك برحمة منا، ونجيناهم من هوان ذلك اليوم وذلَّته. إن ربك -أيها الرسول- هو القوي العزيز، ومِن قوته وعزته أن أهلك الأمم الطاغية، ونجَّى الرسل وأتباعهم."},{"id":"1540","jozz":"12","page":"229","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"8","line_end":"9","aya_no":"67","aya_text":"وَأَخَذَ ٱلَّذِينَ ظَلَمُواْ ٱلصَّيۡحَةُ فَأَصۡبَحُواْ فِي دِيَٰرِهِمۡ جَٰثِمِينَ","aya_text_emlaey":"وأخذ الذين ظلموا الصيحة فأصبحوا في ديارهم جاثمين","aya_tafseer":"[67] وأخذت الصيحة القوية ثمود الظالمين، فأصبحوا في ديارهم موتى هامدين ساقطين على وجوههم لا حَراك بهم."},{"id":"1541","jozz":"12","page":"229","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"10","line_end":"11","aya_no":"68","aya_text":"كَأَن لَّمۡ يَغۡنَوۡاْ فِيهَآۗ أَلَآ إِنَّ ثَمُودَاْ كَفَرُواْ رَبَّهُمۡۗ أَلَا بُعۡدٗا لِّثَمُودَ","aya_text_emlaey":"كأن لم يغنوا فيها ألا إن ثمود كفروا ربهم ألا بعدا لثمود","aya_tafseer":"[68] كأنهم في سرعة زوالهم وفنائهم لم يعيشوا فيها. ألا إن ثمود جحدوا بآيات ربهم وحججه. ألا بُعْداً لثمود وطرداً لهم من رحمة الله، فما أشقاهم وأذلَّهم!"},{"id":"1542","jozz":"12","page":"229","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"11","line_end":"12","aya_no":"69","aya_text":"وَلَقَدۡ جَآءَتۡ رُسُلُنَآ إِبۡرَٰهِيمَ بِٱلۡبُشۡرَىٰ قَالُواْ سَلَٰمٗاۖ قَالَ سَلَٰمٞۖ فَمَا لَبِثَ أَن جَآءَ بِعِجۡلٍ حَنِيذٖ","aya_text_emlaey":"ولقد جاءت رسلنا إبراهيم بالبشرى قالوا سلاما قال سلام فما لبث أن جاء بعجل حنيذ","aya_tafseer":"[69] ولقد جاءت الملائكة إبراهيم - عليه السَّلام - يبشرونه هو وزوجته بإسحاق، ويعقوبَ بعده، فقالوا: سلاماً، قال ردّاً على تحيتهم: سلام، فذهب سريعاً وجاءهم بعجل سمين مشويٍّ ليأكلوا منه."},{"id":"1543","jozz":"12","page":"229","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"12","line_end":"14","aya_no":"70","aya_text":"فَلَمَّا رَءَآ أَيۡدِيَهُمۡ لَا تَصِلُ إِلَيۡهِ نَكِرَهُمۡ وَأَوۡجَسَ مِنۡهُمۡ خِيفَةٗۚ قَالُواْ لَا تَخَفۡ إِنَّآ أُرۡسِلۡنَآ إِلَىٰ قَوۡمِ لُوطٖ","aya_text_emlaey":"فلما رأى أيديهم لا تصل إليه نكرهم وأوجس منهم خيفة قالوا لا تخف إنا أرسلنا إلى قوم لوط","aya_tafseer":"[70] فلما رأى إبراهيم أيديهم لا تَصِل إلى العجل الذي أتاهم به ولا يأكلون منه، أنكر ذلك منهم، وأحس في نفسه خيفة وأضمرها، قالت الملائكة -لما رأت ما بإبراهيم من الخوف-: لا تَخَفْ إنا ملائكة ربك أُرسلنا إلى قوم لوط لإهلاكهم."},{"id":"1544","jozz":"12","page":"229","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"14","line_end":"15","aya_no":"71","aya_text":"وَٱمۡرَأَتُهُۥ قَآئِمَةٞ فَضَحِكَتۡ فَبَشَّرۡنَٰهَا بِإِسۡحَٰقَ وَمِن وَرَآءِ إِسۡحَٰقَ يَعۡقُوبَ","aya_text_emlaey":"وامرأته قائمة فضحكت فبشرناها بإسحاق ومن وراء إسحاق يعقوب","aya_tafseer":"[71] وامرأة إبراهيم -سارة- كانت قائمة من وراء السِّتْر تسمع الكلام، فضحكت تعجباً مما سمعت، فبشرناها - على ألسنة الملائكة - بأنها ستلد مِن زوجها إبراهيم ولداً يسمى إسحاق، وسيعيش ولدها، وسيكون لها بعد إسحاق حفيد منه، وهو يعقوب."},{"id":"1545","jozz":"12","page":"230","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"1","line_end":"2","aya_no":"72","aya_text":"قَالَتۡ يَٰوَيۡلَتَىٰٓ ءَأَلِدُ وَأَنَا۠ عَجُوزٞ وَهَٰذَا بَعۡلِي شَيۡخًاۖ إِنَّ هَٰذَا لَشَيۡءٌ عَجِيبٞ","aya_text_emlaey":"قالت ياويلتى أألد وأنا عجوز وهذا بعلي شيخا إن هذا لشيء عجيب","aya_tafseer":"[72] قالت سارة لما بُشِّرت بإسحاق متعجبة: يا و يلتا كيف يكون لي ولد وأنا عجوز، وهذا زوجي في حال الشيخوخة والكبر؟ إن إنجاب الولد مِن مثلي ومثل زوجي مع كبر السن لَشيء عجيب."},{"id":"1546","jozz":"12","page":"230","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"2","line_end":"3","aya_no":"73","aya_text":"قَالُوٓاْ أَتَعۡجَبِينَ مِنۡ أَمۡرِ ٱللَّهِۖ رَحۡمَتُ ٱللَّهِ وَبَرَكَٰتُهُۥ عَلَيۡكُمۡ أَهۡلَ ٱلۡبَيۡتِۚ إِنَّهُۥ حَمِيدٞ مَّجِيدٞ","aya_text_emlaey":"قالوا أتعجبين من أمر الله رحمة الله وبركاته عليكم أهل البيت إنه حميد مجيد","aya_tafseer":"[73] قالت الرسل لها: أتعجبين من أمر الله وقضائه؟ رحمة الله وبركاته عليكم معشر أهل بيت النبوة. إنه سبحانه وتعالى حميد الصفات والأفعال، ذو مَجْد وعظمة فيها."},{"id":"1547","jozz":"12","page":"230","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"3","line_end":"4","aya_no":"74","aya_text":"فَلَمَّا ذَهَبَ عَنۡ إِبۡرَٰهِيمَ ٱلرَّوۡعُ وَجَآءَتۡهُ ٱلۡبُشۡرَىٰ يُجَٰدِلُنَا فِي قَوۡمِ لُوطٍ","aya_text_emlaey":"فلما ذهب عن إبراهيم الروع وجاءته البشرى يجادلنا في قوم لوط","aya_tafseer":"[74] فلما ذهب عن إبراهيم الخوف الذي انتابه لعدم أكل الضيوف الطعام، وجاءته البشرى بإسحاق ويعقوب، ظلَّ يجادل رسلنا فيما أرسلناهم به من عقاب قوم لوط وإهلاكهم."},{"id":"1548","jozz":"12","page":"230","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"5","line_end":"5","aya_no":"75","aya_text":"إِنَّ إِبۡرَٰهِيمَ لَحَلِيمٌ أَوَّٰهٞ مُّنِيبٞ","aya_text_emlaey":"إن إبراهيم لحليم أواه منيب","aya_tafseer":"[75] إن إبراهيم كثير الحلم لا يحب المعاجلة بالعقاب، كثير التضرع إلى الله والدعاء له، تائب يرجع إلى الله في أموره كلها."},{"id":"1549","jozz":"12","page":"230","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"5","line_end":"6","aya_no":"76","aya_text":"يَٰٓإِبۡرَٰهِيمُ أَعۡرِضۡ عَنۡ هَٰذَآۖ إِنَّهُۥ قَدۡ جَآءَ أَمۡرُ رَبِّكَۖ وَإِنَّهُمۡ ءَاتِيهِمۡ عَذَابٌ غَيۡرُ مَرۡدُودٖ","aya_text_emlaey":"ياإبراهيم أعرض عن هذا إنه قد جاء أمر ربك وإنهم آتيهم عذاب غير مردود","aya_tafseer":"[76] قالت رسل الله: يا إبراهيم أعرض عن هذا الجدال في أمر قوم لوط والتماس الرحمة لهم؛ فإنه قد حق عليهم العذاب، وجاء أمر ربك الذي قدَّره عليهم بهلاكهم، وإنهم نازل بهم عذاب من الله غير مصروف عنهم ولا مدفوع."},{"id":"1550","jozz":"12","page":"230","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"6","line_end":"8","aya_no":"77","aya_text":"وَلَمَّا جَآءَتۡ رُسُلُنَا لُوطٗا سِيٓءَ بِهِمۡ وَضَاقَ بِهِمۡ ذَرۡعٗا وَقَالَ هَٰذَا يَوۡمٌ عَصِيبٞ","aya_text_emlaey":"ولما جاءت رسلنا لوطا سيء بهم وضاق بهم ذرعا وقال هذا يوم عصيب","aya_tafseer":"[77] ولما جاءت ملائكتنا لوطاً ساءه مجيئهم واغتمَّ لذلك؛ وذلك لأنه لم يكن يعلم أنهم رسل الله، فخاف عليهم من قومه، وقال: هذا يوم بلاء وشدة."},{"id":"1551","jozz":"12","page":"230","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"8","line_end":"10","aya_no":"78","aya_text":"وَجَآءَهُۥ قَوۡمُهُۥ يُهۡرَعُونَ إِلَيۡهِ وَمِن قَبۡلُ كَانُواْ يَعۡمَلُونَ ٱلسَّيِّـَٔاتِۚ قَالَ يَٰقَوۡمِ هَٰٓؤُلَآءِ بَنَاتِي هُنَّ أَطۡهَرُ لَكُمۡۖ فَٱتَّقُواْ ٱللَّهَ وَلَا تُخۡزُونِ فِي ضَيۡفِيٓۖ أَلَيۡسَ مِنكُمۡ رَجُلٞ رَّشِيدٞ","aya_text_emlaey":"وجاءه قومه يهرعون إليه ومن قبل كانوا يعملون السيئات قال ياقوم هؤلاء بناتي هن أطهر لكم فاتقوا الله ولا تخزون في ضيفي أليس منكم رجل رشيد","aya_tafseer":"[78] وجاء قومُ لوط يسرعون المشي إليه لطلب الفاحشة، وكانوا مِن قبل مجيئهم يأتون الرجال شهوة دون النساء، فقال لوط لقومه: هؤلاء بناتي تَزَوَّجوهن فهنَّ أطهر لكم مما تريدون، وسماهن بناته؛ لأن نبي الأمة بمنزلة الأب لهم، فاخشوا الله واحذروا عقابه، ولا تفضحوني بالاعتداء على ضيفي، أليس منكم رجل حَسَنُ التقدير للأمور، ينهى من أراد ركوب الفاحشة، فيحول بينهم وبينها، فإهانة الضيف مسَبَّة لا يفعلها إلا أهل السَّفاهة؟"},{"id":"1552","jozz":"12","page":"230","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"11","line_end":"11","aya_no":"79","aya_text":"قَالُواْ لَقَدۡ عَلِمۡتَ مَا لَنَا فِي بَنَاتِكَ مِنۡ حَقّٖ وَإِنَّكَ لَتَعۡلَمُ مَا نُرِيدُ","aya_text_emlaey":"قالوا لقد علمت ما لنا في بناتك من حق وإنك لتعلم ما نريد","aya_tafseer":"[79] قال قوم لوط له: لقد علمتَ من قبلُ أنه ليس لنا في النساء من حاجة أو رغبة، وإنك لتعلم ما نريد، أي لا نريد إلا الرجال ولا رغبة لنا في نكاح النساء."},{"id":"1553","jozz":"12","page":"230","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"12","line_end":"12","aya_no":"80","aya_text":"قَالَ لَوۡ أَنَّ لِي بِكُمۡ قُوَّةً أَوۡ ءَاوِيٓ إِلَىٰ رُكۡنٖ شَدِيدٖ","aya_text_emlaey":"قال لو أن لي بكم قوة أو آوي إلى ركن شديد","aya_tafseer":"[80] قال لهم حين أبَوْا إلا فعل الفاحشة: لو أن لي بكم قوة وأنصاراً معي، أو أركَن إلى عشيرة تمنعني منكم، لَحُلْتُ بينكم وبين ما تريدون."},{"id":"1554","jozz":"12","page":"230","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"12","line_end":"15","aya_no":"81","aya_text":"قَالُواْ يَٰلُوطُ إِنَّا رُسُلُ رَبِّكَ لَن يَصِلُوٓاْ إِلَيۡكَۖ فَأَسۡرِ بِأَهۡلِكَ بِقِطۡعٖ مِّنَ ٱلَّيۡلِ وَلَا يَلۡتَفِتۡ مِنكُمۡ أَحَدٌ إِلَّا ٱمۡرَأَتَكَۖ إِنَّهُۥ مُصِيبُهَا مَآ أَصَابَهُمۡۚ إِنَّ مَوۡعِدَهُمُ ٱلصُّبۡحُۚ أَلَيۡسَ ٱلصُّبۡحُ بِقَرِيبٖ","aya_text_emlaey":"قالوا يالوط إنا رسل ربك لن يصلوا إليك فأسر بأهلك بقطع من الليل ولا يلتفت منكم أحد إلا امرأتك إنه مصيبها ما أصابهم إن موعدهم الصبح أليس الصبح بقريب","aya_tafseer":"[81] قالت الملائكة: يا لوط إنَّا رسل ربك أرْسَلَنا لإهلاك قومك، وإنهم لن يصلوا إليك، فاخرج من هذه القرية أنت وأهلك ببقية من الليل، ولا يلتفت منكم أحد وراءه؛ لئلا يرى العذاب فيصيبه، لكنَّ امرأتك التي خانتك بالكفر والنفاق سيصيبها ما أصاب قومك من الهلاك، إن موعد هلاكهم الصبح، وهو موعد قريب الحلول."},{"id":"1555","jozz":"12","page":"231","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"1","line_end":"2","aya_no":"82","aya_text":"فَلَمَّا جَآءَ أَمۡرُنَا جَعَلۡنَا عَٰلِيَهَا سَافِلَهَا وَأَمۡطَرۡنَا عَلَيۡهَا حِجَارَةٗ مِّن سِجِّيلٖ مَّنضُودٖ","aya_text_emlaey":"فلما جاء أمرنا جعلنا عاليها سافلها وأمطرنا عليها حجارة من سجيل منضود","aya_tafseer":"[82] فلما جاء أمرنا بنزول العذاب بهم جعلنا عاليَ قراهم التي كانوا يعيشون فيها سافلها فقلبناها، وأمطرنا عليهم حجارة من طين متصلِّب متين، قد صُفَّ بعضها إلى بعض متتابعة"},{"id":"1556","jozz":"12","page":"231","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"2","line_end":"3","aya_no":"83","aya_text":"مُّسَوَّمَةً عِندَ رَبِّكَۖ وَمَا هِيَ مِنَ ٱلظَّٰلِمِينَ بِبَعِيدٖ","aya_text_emlaey":"مسومة عند ربك وما هي من الظالمين ببعيد","aya_tafseer":"[83] معلَّمة عند الله بعلامة معروفة لا تشاكِل حجارة الأرض، وما هذه الحجارة التي أمطرها الله على قوم لوط من كفار قريش ببعيد أن يُمْطَروا بمثلها. وفي هذا تهديد لكل عاص متمرِّد على الله."},{"id":"1557","jozz":"12","page":"231","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"3","line_end":"6","aya_no":"84","aya_text":"۞ وَإِلَىٰ مَدۡيَنَ أَخَاهُمۡ شُعَيۡبٗاۚ قَالَ يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥۖ وَلَا تَنقُصُواْ ٱلۡمِكۡيَالَ وَٱلۡمِيزَانَۖ إِنِّيٓ أَرَىٰكُم بِخَيۡرٖ وَإِنِّيٓ أَخَافُ عَلَيۡكُمۡ عَذَابَ يَوۡمٖ مُّحِيطٖ","aya_text_emlaey":"وإلى مدين أخاهم شعيبا قال ياقوم اعبدوا الله ما لكم من إله غيره ولا تنقصوا المكيال والميزان إني أراكم بخير وإني أخاف عليكم عذاب يوم محيط","aya_tafseer":"[84] وأرسلنا إلى «مدين» أخاهم شعيباً، فقال: يا قوم اعبدوا الله وحده، ليس لكم مِن إله يستحق العبادة غيره جلَّ وعلا، فأخلصوا له العبادة، ولا تنقصوا الناس حقوقهم في مكاييلهم وموازينهم، إني أراكم في سَعَة عيش، وإني أخاف عليكم -بسبب إنقاص المكيال والميزان- عذاب يوم يحيط بكم."},{"id":"1558","jozz":"12","page":"231","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"6","line_end":"8","aya_no":"85","aya_text":"وَيَٰقَوۡمِ أَوۡفُواْ ٱلۡمِكۡيَالَ وَٱلۡمِيزَانَ بِٱلۡقِسۡطِۖ وَلَا تَبۡخَسُواْ ٱلنَّاسَ أَشۡيَآءَهُمۡ وَلَا تَعۡثَوۡاْ فِي ٱلۡأَرۡضِ مُفۡسِدِينَ","aya_text_emlaey":"وياقوم أوفوا المكيال والميزان بالقسط ولا تبخسوا الناس أشياءهم ولا تعثوا في الأرض مفسدين","aya_tafseer":"[85] ويا قوم أتمُّوا المكيال والميزان بالعدل، ولا تُنقِصوا الناس حقهم في عموم أشيائهم، ولا تسيروا في الأرض تعملون فيها بمعاصي الله ونشر الفساد."},{"id":"1559","jozz":"12","page":"231","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"8","line_end":"10","aya_no":"86","aya_text":"بَقِيَّتُ ٱللَّهِ خَيۡرٞ لَّكُمۡ إِن كُنتُم مُّؤۡمِنِينَۚ وَمَآ أَنَا۠ عَلَيۡكُم بِحَفِيظٖ","aya_text_emlaey":"بقية الله خير لكم إن كنتم مؤمنين وما أنا عليكم بحفيظ","aya_tafseer":"[86] إن ما يبقى لكم بعد إيفاء الكيل والميزان من الربح الحلال فيه بَرَكة وخير لكم ممَّا تأخذونه بالتطفيف ونحوه من الكسب الحرام، إن كنتم تؤمنون بالله حقّاً، فامتثلوا أمره، وما أنا عليكم برقيب أحصي عليكم أعمالكم."},{"id":"1560","jozz":"12","page":"231","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"10","line_end":"12","aya_no":"87","aya_text":"قَالُواْ يَٰشُعَيۡبُ أَصَلَوٰتُكَ تَأۡمُرُكَ أَن نَّتۡرُكَ مَا يَعۡبُدُ ءَابَآؤُنَآ أَوۡ أَن نَّفۡعَلَ فِيٓ أَمۡوَٰلِنَا مَا نَشَٰٓؤُاْۖ إِنَّكَ لَأَنتَ ٱلۡحَلِيمُ ٱلرَّشِيدُ","aya_text_emlaey":"قالوا ياشعيب أصلاتك تأمرك أن نترك ما يعبد آباؤنا أو أن نفعل في أموالنا ما نشاء إنك لأنت الحليم الرشيد","aya_tafseer":"[87] قالوا: يا شعيب أهذه الصلاة التي تداوم عليها تأمرك بأن نترك ما يعبده آباؤنا من الأصنام والأوثان، أو أن نمتنع عن التصرف في كسب أموالنا بما نستطيع من احتيال ومكر؟ وقالوا -استهزاءً به-: إنك لأنت العاقِلُ الحسنُ التدبير في المال."},{"id":"1561","jozz":"12","page":"231","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"12","line_end":"15","aya_no":"88","aya_text":"قَالَ يَٰقَوۡمِ أَرَءَيۡتُمۡ إِن كُنتُ عَلَىٰ بَيِّنَةٖ مِّن رَّبِّي وَرَزَقَنِي مِنۡهُ رِزۡقًا حَسَنٗاۚ وَمَآ أُرِيدُ أَنۡ أُخَالِفَكُمۡ إِلَىٰ مَآ أَنۡهَىٰكُمۡ عَنۡهُۚ إِنۡ أُرِيدُ إِلَّا ٱلۡإِصۡلَٰحَ مَا ٱسۡتَطَعۡتُۚ وَمَا تَوۡفِيقِيٓ إِلَّا بِٱللَّهِۚ عَلَيۡهِ تَوَكَّلۡتُ وَإِلَيۡهِ أُنِيبُ","aya_text_emlaey":"قال ياقوم أرأيتم إن كنت على بينة من ربي ورزقني منه رزقا حسنا وما أريد أن أخالفكم إلى ما أنهاكم عنه إن أريد إلا الإصلاح ما استطعت وما توفيقي إلا بالله عليه توكلت وإليه أنيب","aya_tafseer":"[88] قال شعيب: يا قوم أرأيتم إن كنت على طريق واضح من ربي فيما أدعوكم إليه من إخلاص العبادة له، وفيما أنهاكم عنه من إفساد المال، ورزقني منه رزقاً واسعاً حلالاً طيباً؟ وما أريد أن أخالفكم فأرتكب أمراً نهيتكم عنه، وما أريد فيما آمركم به وأنهاكم عنه إلا إصلاحكم قَدْر طاقتي واستطاعتي، وما توفيقي -في إصابة الحق ومحاولة إصلاحكم- إلا بالله، على الله وحده توكلت وإليه أرجع بالتوبة والإنابة."},{"id":"1562","jozz":"12","page":"232","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"1","line_end":"3","aya_no":"89","aya_text":"وَيَٰقَوۡمِ لَا يَجۡرِمَنَّكُمۡ شِقَاقِيٓ أَن يُصِيبَكُم مِّثۡلُ مَآ أَصَابَ قَوۡمَ نُوحٍ أَوۡ قَوۡمَ هُودٍ أَوۡ قَوۡمَ صَٰلِحٖۚ وَمَا قَوۡمُ لُوطٖ مِّنكُم بِبَعِيدٖ","aya_text_emlaey":"وياقوم لا يجرمنكم شقاقي أن يصيبكم مثل ما أصاب قوم نوح أو قوم هود أو قوم صالح وما قوم لوط منكم ببعيد","aya_tafseer":"[89] ويا قوم لا تحملنَّكم عداوتي وبغضي وفراق الدين الذي أنا عليه على العناد والإصرار على ما أنتم عليه من الكفر بالله، فيصيبكم مثلُ ما أصاب قوم نوح أو قوم هود أو قوم صالح من الهلاك، وما قوم لوط وما حلَّ بهم من العذاب ببعيدين عنكم لا في الدار ولا في الزمان."},{"id":"1563","jozz":"12","page":"232","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"3","line_end":"4","aya_no":"90","aya_text":"وَٱسۡتَغۡفِرُواْ رَبَّكُمۡ ثُمَّ تُوبُوٓاْ إِلَيۡهِۚ إِنَّ رَبِّي رَحِيمٞ وَدُودٞ","aya_text_emlaey":"واستغفروا ربكم ثم توبوا إليه إن ربي رحيم ودود","aya_tafseer":"[90] واطلبوا من ربِّكم المغفرة لذنوبكم، ثم ارجعوا إلى طاعته واستمروا عليها. إن ربِّي رحيم كثير المودَّة والمحبة لمن تاب إليه وأناب، يرحمه ويقبل توبته. وفي الآية إثبات صفة الرحمة والمودة لله تعالى، كما يليق به سبحانه."},{"id":"1564","jozz":"12","page":"232","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"4","line_end":"6","aya_no":"91","aya_text":"قَالُواْ يَٰشُعَيۡبُ مَا نَفۡقَهُ كَثِيرٗا مِّمَّا تَقُولُ وَإِنَّا لَنَرَىٰكَ فِينَا ضَعِيفٗاۖ وَلَوۡلَا رَهۡطُكَ لَرَجَمۡنَٰكَۖ وَمَآ أَنتَ عَلَيۡنَا بِعَزِيزٖ","aya_text_emlaey":"قالوا ياشعيب ما نفقه كثيرا مما تقول وإنا لنراك فينا ضعيفا ولولا رهطك لرجمناك وما أنت علينا بعزيز","aya_tafseer":"[91] قالوا: يا شعيب ما نفقه كثيراً مما تقول، وإننا لَنراك فينا ضعيفاً لست من الكبراء ولا من الرؤساء، ولولا مراعاة عشيرتك لقتلناك رجْماً بالحجارة -وكان رهطه من أهل ملتهم-، وليس لك قَدْر واحترام في نفوسنا."},{"id":"1565","jozz":"12","page":"232","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"6","line_end":"8","aya_no":"92","aya_text":"قَالَ يَٰقَوۡمِ أَرَهۡطِيٓ أَعَزُّ عَلَيۡكُم مِّنَ ٱللَّهِ وَٱتَّخَذۡتُمُوهُ وَرَآءَكُمۡ ظِهۡرِيًّاۖ إِنَّ رَبِّي بِمَا تَعۡمَلُونَ مُحِيطٞ","aya_text_emlaey":"قال ياقوم أرهطي أعز عليكم من الله واتخذتموه وراءكم ظهريا إن ربي بما تعملون محيط","aya_tafseer":"[92] قال: يا قوم أعشيرتي أعزُّ وأكرم عليكم من الله؟ ونبذتم أمر ربكم فجعلتموه خلف ظهوركم، لا تأتمرون به ولا تنتهون بنهيه، إن ربي بما تعملون محيط، لا يخفى عليه من أعمالكم مثقال ذرة، وسيجازيكم عليها عاجلاً وآجلاً."},{"id":"1566","jozz":"12","page":"232","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"8","line_end":"10","aya_no":"93","aya_text":"وَيَٰقَوۡمِ ٱعۡمَلُواْ عَلَىٰ مَكَانَتِكُمۡ إِنِّي عَٰمِلٞۖ سَوۡفَ تَعۡلَمُونَ مَن يَأۡتِيهِ عَذَابٞ يُخۡزِيهِ وَمَنۡ هُوَ كَٰذِبٞۖ وَٱرۡتَقِبُوٓاْ إِنِّي مَعَكُمۡ رَقِيبٞ","aya_text_emlaey":"وياقوم اعملوا على مكانتكم إني عامل سوف تعلمون من يأتيه عذاب يخزيه ومن هو كاذب وارتقبوا إني معكم رقيب","aya_tafseer":"[93] ويا قوم اعملوا كل ما تستطيعون على طريقتكم وحالتكم، إني عامل مثابر على طريقتي وما وهبني ربي مِن دعوتكم إلى التوحيد، سوف تعلمون مَن منا يأتيه عذاب يذلُّه، ومَن منا كاذب في قوله، أنا أم أنتم؟ وانتظروا ما سَيَحِلُّ بكم إني معكم من المنتظرين. وهذا تهديد شديد لهم."},{"id":"1567","jozz":"12","page":"232","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"10","line_end":"12","aya_no":"94","aya_text":"وَلَمَّا جَآءَ أَمۡرُنَا نَجَّيۡنَا شُعَيۡبٗا وَٱلَّذِينَ ءَامَنُواْ مَعَهُۥ بِرَحۡمَةٖ مِّنَّا وَأَخَذَتِ ٱلَّذِينَ ظَلَمُواْ ٱلصَّيۡحَةُ فَأَصۡبَحُواْ فِي دِيَٰرِهِمۡ جَٰثِمِينَ","aya_text_emlaey":"ولما جاء أمرنا نجينا شعيبا والذين آمنوا معه برحمة منا وأخذت الذين ظلموا الصيحة فأصبحوا في ديارهم جاثمين","aya_tafseer":"[94] ولما جاء أمرنا بإهلاك قوم شعيب نجَّينا رسولنا شعيباً والذين آمنوا معه برحمة منا، وأخذت الذين ظلموا الصيحة من السماء، فأهلكتهم، فأصبحوا في ديارهم باركين على رُكَبهم ميتين لا حَرَاك بهم."},{"id":"1568","jozz":"12","page":"232","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"13","line_end":"13","aya_no":"95","aya_text":"كَأَن لَّمۡ يَغۡنَوۡاْ فِيهَآۗ أَلَا بُعۡدٗا لِّمَدۡيَنَ كَمَا بَعِدَتۡ ثَمُودُ","aya_text_emlaey":"كأن لم يغنوا فيها ألا بعدا لمدين كما بعدت ثمود","aya_tafseer":"[95] كأن لم يقيموا في ديارهم وقتاً من الأوقات. ألا بُعْداً ﻟ«مدين» -إذ أهلكها الله وأخزاها- كما بَعِدت ثمود، فقد اشتركت هاتان القبيلتان في البعد والهلاك."},{"id":"1569","jozz":"12","page":"232","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"14","line_end":"14","aya_no":"96","aya_text":"وَلَقَدۡ أَرۡسَلۡنَا مُوسَىٰ بِـَٔايَٰتِنَا وَسُلۡطَٰنٖ مُّبِينٍ","aya_text_emlaey":"ولقد أرسلنا موسى بآياتنا وسلطان مبين","aya_tafseer":"[96] ولقد أرسلنا موسى بأدلتنا على توحيدنا وحجة تبين لمن عاينها وتأملها -بقلب صحيح- أنها تدل على وحدانية الله، وكَذِبِ كلِّ مَن ادَّعى الربوبية دونه سبحانه وتعالى."},{"id":"1570","jozz":"12","page":"232","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"14","line_end":"15","aya_no":"97","aya_text":"إِلَىٰ فِرۡعَوۡنَ وَمَلَإِيْهِۦ فَٱتَّبَعُوٓاْ أَمۡرَ فِرۡعَوۡنَۖ وَمَآ أَمۡرُ فِرۡعَوۡنَ بِرَشِيدٖ","aya_text_emlaey":"إلى فرعون وملئه فاتبعوا أمر فرعون وما أمر فرعون برشيد","aya_tafseer":"[97] أرسلنا موسى إلى فرعون وأكابر أتباعه وأشراف قومه، فكفر فرعون، وأمر قومه أن يتبعوه فأطاعوه، وخالفوا أمر موسى، وليس في أمر فرعون رشد ولا هدى، وإنما هو جهل وضلال وكفر وعناد."},{"id":"1571","jozz":"12","page":"233","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"1","line_end":"2","aya_no":"98","aya_text":"يَقۡدُمُ قَوۡمَهُۥ يَوۡمَ ٱلۡقِيَٰمَةِ فَأَوۡرَدَهُمُ ٱلنَّارَۖ وَبِئۡسَ ٱلۡوِرۡدُ ٱلۡمَوۡرُودُ","aya_text_emlaey":"يقدم قومه يوم القيامة فأوردهم النار وبئس الورد المورود","aya_tafseer":"[98] يَقْدُم فرعون قومه يوم القيامة حتى يدخلهم النار، وقبُح المدخل الذي يدخلونه."},{"id":"1572","jozz":"12","page":"233","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"2","line_end":"3","aya_no":"99","aya_text":"وَأُتۡبِعُواْ فِي هَٰذِهِۦ لَعۡنَةٗ وَيَوۡمَ ٱلۡقِيَٰمَةِۚ بِئۡسَ ٱلرِّفۡدُ ٱلۡمَرۡفُودُ","aya_text_emlaey":"وأتبعوا في هذه لعنة ويوم القيامة بئس الرفد المرفود","aya_tafseer":"[99] وأتبعهم الله في هذه الدنيا مع العذاب الذي عجَّله لهم فيها من الغرق في البحر لعنةً، ويوم القيامة كذلك لعنة أخرى بإدخالهم النار، وبئس ما اجتمع لهم وترادَف عليهم من عذاب الله، ولعنة الدنيا والآخرة."},{"id":"1573","jozz":"12","page":"233","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"3","line_end":"4","aya_no":"100","aya_text":"ذَٰلِكَ مِنۡ أَنۢبَآءِ ٱلۡقُرَىٰ نَقُصُّهُۥ عَلَيۡكَۖ مِنۡهَا قَآئِمٞ وَحَصِيدٞ","aya_text_emlaey":"ذلك من أنباء القرى نقصه عليك منها قائم وحصيد","aya_tafseer":"[100] ذلك الذي ذكرناه لك -أيها الرسول- من أخبار القرى التي أهلكنا أهلها نخبرك به، ومن تلك القرى ما له آثار باقية، ومنها ما قد مُحِيَتْ آثاره، فلم يَبْقَ منه شيء."},{"id":"1574","jozz":"12","page":"233","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"4","line_end":"6","aya_no":"101","aya_text":"وَمَا ظَلَمۡنَٰهُمۡ وَلَٰكِن ظَلَمُوٓاْ أَنفُسَهُمۡۖ فَمَآ أَغۡنَتۡ عَنۡهُمۡ ءَالِهَتُهُمُ ٱلَّتِي يَدۡعُونَ مِن دُونِ ٱللَّهِ مِن شَيۡءٖ لَّمَّا جَآءَ أَمۡرُ رَبِّكَۖ وَمَا زَادُوهُمۡ غَيۡرَ تَتۡبِيبٖ","aya_text_emlaey":"وما ظلمناهم ولكن ظلموا أنفسهم فما أغنت عنهم آلهتهم التي يدعون من دون الله من شيء لما جاء أمر ربك وما زادوهم غير تتبيب","aya_tafseer":"[101] وما كان إهلاكهم بغير سبب وذنب يستحقونه، ولكن ظلموا أنفسهم بشركهم وإفسادهم في الأرض، فما نفعتهم آلهتهم التي كانوا يدعُونها ويطلبون منها أن تدفع عنهم الضر لمَّا جاء أمر ربك بعذابهم، وما زادتهم آلهتهم غير تدمير وإهلاك وخسران."},{"id":"1575","jozz":"12","page":"233","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"7","line_end":"8","aya_no":"102","aya_text":"وَكَذَٰلِكَ أَخۡذُ رَبِّكَ إِذَآ أَخَذَ ٱلۡقُرَىٰ وَهِيَ ظَٰلِمَةٌۚ إِنَّ أَخۡذَهُۥٓ أَلِيمٞ شَدِيدٌ","aya_text_emlaey":"وكذلك أخذ ربك إذا أخذ القرى وهي ظالمة إن أخذه أليم شديد","aya_tafseer":"[102] وكما أخذتُ أهل القرى الظالمةِ بالعذاب لمخالفتهم أمري وتكذيبهم برسلي، آخذ غيرهم مِن أهل القرى إذا ظلموا أنفسهم بكفرهم بالله ومعصيتهم له وتكذيبهم لرسله. إنَّ أَخْذه بالعقوبة لأليم موجع شديد."},{"id":"1576","jozz":"12","page":"233","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"8","line_end":"9","aya_no":"103","aya_text":"إِنَّ فِي ذَٰلِكَ لَأٓيَةٗ لِّمَنۡ خَافَ عَذَابَ ٱلۡأٓخِرَةِۚ ذَٰلِكَ يَوۡمٞ مَّجۡمُوعٞ لَّهُ ٱلنَّاسُ وَذَٰلِكَ يَوۡمٞ مَّشۡهُودٞ","aya_text_emlaey":"إن في ذلك لآية لمن خاف عذاب الآخرة ذلك يوم مجموع له الناس وذلك يوم مشهود","aya_tafseer":"[103] إن في أخذنا لأهل القرى السابقة الظالمة لعبرةً وعظة لمن خاف عقاب الله وعذابه في الآخرة، ذلك اليوم الذي يُجمع له الناس جميعاً للمحاسبة والجزاء، ويشهده الخلائق كلهم."},{"id":"1577","jozz":"12","page":"233","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"10","line_end":"10","aya_no":"104","aya_text":"وَمَا نُؤَخِّرُهُۥٓ إِلَّا لِأَجَلٖ مَّعۡدُودٖ","aya_text_emlaey":"وما نؤخره إلا لأجل معدود","aya_tafseer":"[104] وما نؤخر يوم القيامة عنكم إلا لانتهاء مدة معدودة في علمنا، لا تزيد ولا تنقص عن تقديرنا لها بحكمتنا."},{"id":"1578","jozz":"12","page":"233","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"10","line_end":"11","aya_no":"105","aya_text":"يَوۡمَ يَأۡتِ لَا تَكَلَّمُ نَفۡسٌ إِلَّا بِإِذۡنِهِۦۚ فَمِنۡهُمۡ شَقِيّٞ وَسَعِيدٞ","aya_text_emlaey":"يوم يأت لا تكلم نفس إلا بإذنه فمنهم شقي وسعيد","aya_tafseer":"[105] يوم يأتي يوم القيامة، لا تتكلم نفس إلا بإذن ربها، فمنهم شقي مستحق للعذاب، وسعيد متفضَّل عليه بالنعيم."},{"id":"1579","jozz":"12","page":"233","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"11","line_end":"12","aya_no":"106","aya_text":"فَأَمَّا ٱلَّذِينَ شَقُواْ فَفِي ٱلنَّارِ لَهُمۡ فِيهَا زَفِيرٞ وَشَهِيقٌ","aya_text_emlaey":"فأما الذين شقوا ففي النار لهم فيها زفير وشهيق","aya_tafseer":"[106] فأما الذين شَقُوا في الدنيا لفساد عقيدتهم وسوء أعمالهم، فالنار مستقرهم، لهم فيها -من شدة ما هم فيه من العذاب- إخراج النَّفَس من الصَّدْر بدَفْعٍ وردُّه إليه بشدَّة، وهما أشنع الأصوات وأقبحها"},{"id":"1580","jozz":"12","page":"233","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"12","line_end":"13","aya_no":"107","aya_text":"خَٰلِدِينَ فِيهَا مَا دَامَتِ ٱلسَّمَٰوَٰتُ وَٱلۡأَرۡضُ إِلَّا مَا شَآءَ رَبُّكَۚ إِنَّ رَبَّكَ فَعَّالٞ لِّمَا يُرِيدُ","aya_text_emlaey":"خالدين فيها ما دامت السموات والأرض إلا ما شاء ربك إن ربك فعال لما يريد","aya_tafseer":"[107] ماكثين في النار أبداً ما دامت السموات والأرض، فلا ينقطع عذابهم ولا ينتهي، بل هو دائم مؤكَّد، إلا ما شاء ربك من إخراج عصاة الموحدين بعد مدَّة من مكثهم في النار. إن ربك -أيها الرسول- فعَّال لما يريد."},{"id":"1581","jozz":"12","page":"233","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"14","line_end":"15","aya_no":"108","aya_text":"۞ وَأَمَّا ٱلَّذِينَ سُعِدُواْ فَفِي ٱلۡجَنَّةِ خَٰلِدِينَ فِيهَا مَا دَامَتِ ٱلسَّمَٰوَٰتُ وَٱلۡأَرۡضُ إِلَّا مَا شَآءَ رَبُّكَۖ عَطَآءً غَيۡرَ مَجۡذُوذٖ","aya_text_emlaey":"وأما الذين سعدوا ففي الجنة خالدين فيها ما دامت السموات والأرض إلا ما شاء ربك عطاء غير مجذوذ","aya_tafseer":"[108] وأما الذين رزقهم الله السعادة فيدخلون الجنة خالدين فيها ما دامت السموات والأرض، إلا الفريق الذي شاء الله تأخيره، وهم عصاة الموحدين، فإنهم يبقون في النار فترة من الزمن، ثم يخرجون منها إلى الجنة بمشيئة الله ورحمته، ويعطي ربك هؤلاء السعداء في الجنة عطاء غير مقطوع عنهم."},{"id":"1582","jozz":"12","page":"234","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"1","line_end":"2","aya_no":"109","aya_text":"فَلَا تَكُ فِي مِرۡيَةٖ مِّمَّا يَعۡبُدُ هَٰٓؤُلَآءِۚ مَا يَعۡبُدُونَ إِلَّا كَمَا يَعۡبُدُ ءَابَآؤُهُم مِّن قَبۡلُۚ وَإِنَّا لَمُوَفُّوهُمۡ نَصِيبَهُمۡ غَيۡرَ مَنقُوصٖ","aya_text_emlaey":"فلا تك في مرية مما يعبد هؤلاء ما يعبدون إلا كما يعبد آباؤهم من قبل وإنا لموفوهم نصيبهم غير منقوص","aya_tafseer":"[109] فلا تكن- أيها الرسول- في شك من بطلان ما يعبد هؤلاء المشركون من قومك، ما يعبدون من الأوثان إلا مثل ما يعبد آباؤهم من قبل، وإنَّا لموفوهم ما وعدناهم تامّاً غير منقوص. وهذا توجيه لجميع الأمَّة، وإن كان لفظه موجهاً إلى الرسول -صلى الله عليه وسلم-."},{"id":"1583","jozz":"12","page":"234","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"3","line_end":"4","aya_no":"110","aya_text":"وَلَقَدۡ ءَاتَيۡنَا مُوسَى ٱلۡكِتَٰبَ فَٱخۡتُلِفَ فِيهِۚ وَلَوۡلَا كَلِمَةٞ سَبَقَتۡ مِن رَّبِّكَ لَقُضِيَ بَيۡنَهُمۡۚ وَإِنَّهُمۡ لَفِي شَكّٖ مِّنۡهُ مُرِيبٖ","aya_text_emlaey":"ولقد آتينا موسى الكتاب فاختلف فيه ولولا كلمة سبقت من ربك لقضي بينهم وإنهم لفي شك منه مريب","aya_tafseer":"[110] ولقد آتينا موسى الكتاب وهو التوراة، فاختلف فيه قومه، فآمن به جماعة وكفر به آخرون، كما فعل قومك بالقرآن. ولولا كلمة سبقت من ربك بأنه لا يعجل لخلقه العذاب، لحلَّ بهم في دنياهم قضاء الله بإهلاك المكذِّبين ونجاة المؤمنين. وإن الكفار من اليهود والمشركين -أيها الرسول- لفي شك -من هذا القرآن- مريب."},{"id":"1584","jozz":"12","page":"234","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"5","line_end":"6","aya_no":"111","aya_text":"وَإِنَّ كُلّٗا لَّمَّا لَيُوَفِّيَنَّهُمۡ رَبُّكَ أَعۡمَٰلَهُمۡۚ إِنَّهُۥ بِمَا يَعۡمَلُونَ خَبِيرٞ","aya_text_emlaey":"وإن كلا لما ليوفينهم ربك أعمالهم إنه بما يعملون خبير","aya_tafseer":"[111] وإن كل أولئك الأقوام المختلفين الذين ذكرنا لك -أيها الرسول- أخبارهم ليوفينهم ربك جزاء أعمالهم يوم القيامة، إن خيراً فخير، وإن شرّاً فشر، إن ربك بما يعمل هؤلاء المشركون خبير، لا يخفى عليه شيء مِن عملهم. وفي هذا تهديد ووعيد لهم."},{"id":"1585","jozz":"12","page":"234","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"6","line_end":"7","aya_no":"112","aya_text":"فَٱسۡتَقِمۡ كَمَآ أُمِرۡتَ وَمَن تَابَ مَعَكَ وَلَا تَطۡغَوۡاْۚ إِنَّهُۥ بِمَا تَعۡمَلُونَ بَصِيرٞ","aya_text_emlaey":"فاستقم كما أمرت ومن تاب معك ولا تطغوا إنه بما تعملون بصير","aya_tafseer":"[112] فاستقم -أيها النبي- كما أمرك ربك أنت ومَن تاب معك، ولا تتجاوزوا ما حدَّه الله لكم، إن ربَّكم بما تعملون من الأعمال كلها بصير، لا يخفى عليه شيء منها، وسيجازيكم عليها."},{"id":"1586","jozz":"12","page":"234","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"7","line_end":"9","aya_no":"113","aya_text":"وَلَا تَرۡكَنُوٓاْ إِلَى ٱلَّذِينَ ظَلَمُواْ فَتَمَسَّكُمُ ٱلنَّارُ وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِنۡ أَوۡلِيَآءَ ثُمَّ لَا تُنصَرُونَ","aya_text_emlaey":"ولا تركنوا إلى الذين ظلموا فتمسكم النار وما لكم من دون الله من أولياء ثم لا تنصرون","aya_tafseer":"[113] ولا تميلوا إلى هؤلاء الكفار الظلمة، فتصيبكم النار، وما لكم من دون الله من ناصر ينصركم، ويتولى أموركم."},{"id":"1587","jozz":"12","page":"234","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"9","line_end":"11","aya_no":"114","aya_text":"وَأَقِمِ ٱلصَّلَوٰةَ طَرَفَيِ ٱلنَّهَارِ وَزُلَفٗا مِّنَ ٱلَّيۡلِۚ إِنَّ ٱلۡحَسَنَٰتِ يُذۡهِبۡنَ ٱلسَّيِّـَٔاتِۚ ذَٰلِكَ ذِكۡرَىٰ لِلذَّٰكِرِينَ","aya_text_emlaey":"وأقم الصلاة طرفي النهار وزلفا من الليل إن الحسنات يذهبن السيئات ذلك ذكرى للذاكرين","aya_tafseer":"[114] وأدِّ الصلاة -أيها النبي- على أتمِّ وجه، طَرَفَي النهار في الصباح والمساء، وفي ساعات من الليل. إنَّ فِعْلَ الخيرات يكفِّر الذنوب السالفة ويمحو آثارها، والأمر بإقامة الصلاة وبيان أن الحسنات يذهبن السيئات، موعظة لمن اتعظ بها وتذكر."},{"id":"1588","jozz":"12","page":"234","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"11","line_end":"11","aya_no":"115","aya_text":"وَٱصۡبِرۡ فَإِنَّ ٱللَّهَ لَا يُضِيعُ أَجۡرَ ٱلۡمُحۡسِنِينَ","aya_text_emlaey":"واصبر فإن الله لا يضيع أجر المحسنين","aya_tafseer":"[115] واصبر -أيها النبي- على الصلاة، وعلى ما تَلْقى من الأذى من مشركي قومك؛ فإن الله لا يضيع ثواب المحسنين في أعمالهم."},{"id":"1589","jozz":"12","page":"234","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"12","line_end":"14","aya_no":"116","aya_text":"فَلَوۡلَا كَانَ مِنَ ٱلۡقُرُونِ مِن قَبۡلِكُمۡ أُوْلُواْ بَقِيَّةٖ يَنۡهَوۡنَ عَنِ ٱلۡفَسَادِ فِي ٱلۡأَرۡضِ إِلَّا قَلِيلٗا مِّمَّنۡ أَنجَيۡنَا مِنۡهُمۡۗ وَٱتَّبَعَ ٱلَّذِينَ ظَلَمُواْ مَآ أُتۡرِفُواْ فِيهِ وَكَانُواْ مُجۡرِمِينَ","aya_text_emlaey":"فلولا كان من القرون من قبلكم أولو بقية ينهون عن الفساد في الأرض إلا قليلا ممن أنجينا منهم واتبع الذين ظلموا ما أترفوا فيه وكانوا مجرمين","aya_tafseer":"[116] فهلَّا وُجد من القرون الماضية بقايا من أهل الخير والصلاح، ينهَوْن أهل الكفر عن كفرهم، وعن الفساد في الأرض، لم يوجد من أولئك الأقوام إلا قليل ممن آمن، فنجَّاهم الله بسبب ذلك مِن عذابه حين أخذ الظالمين. واتَّبع الذين ظلموا أنفسهم من كلِّ أمَّة سَلَفت ما مُتِّعوا فيه من لذات الدنيا ونعيمها، وكانوا مجرمين ظالمين باتباعهم ما تَنَعَّموا فيه، فحقَّ عليهم العذاب. وفي الآية عبرة وموعظة للعصاةِ من المسلمين؛ لأنهم لا يَخْلُون من ظلمِ أنفسهم."},{"id":"1590","jozz":"12","page":"234","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"14","line_end":"15","aya_no":"117","aya_text":"وَمَا كَانَ رَبُّكَ لِيُهۡلِكَ ٱلۡقُرَىٰ بِظُلۡمٖ وَأَهۡلُهَا مُصۡلِحُونَ","aya_text_emlaey":"وما كان ربك ليهلك القرى بظلم وأهلها مصلحون","aya_tafseer":"[117] وما كان ربك -أيها الرسول- ليهلك قرية من القرى وأهلها مصلحون في الأرض، مجتنبون للفساد والظلم، وإنما يهلكهم بسبب ظلمهم وفسادهم."},{"id":"1591","jozz":"12","page":"235","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"1","line_end":"1","aya_no":"118","aya_text":"وَلَوۡ شَآءَ رَبُّكَ لَجَعَلَ ٱلنَّاسَ أُمَّةٗ وَٰحِدَةٗۖ وَلَا يَزَالُونَ مُخۡتَلِفِينَ","aya_text_emlaey":"ولو شاء ربك لجعل الناس أمة واحدة ولا يزالون مختلفين","aya_tafseer":"[118] ولو شاء ربك لجعل الناس كلهم جماعة واحدة على دين واحد وهو دين الإسلام، ولكنه سبحانه لم يشأ ذلك، فلا يزال الناس مختلفين في أديانهم؛ وذلك مقتضى حكمته."},{"id":"1592","jozz":"12","page":"235","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"2","line_end":"3","aya_no":"119","aya_text":"إِلَّا مَن رَّحِمَ رَبُّكَۚ وَلِذَٰلِكَ خَلَقَهُمۡۗ وَتَمَّتۡ كَلِمَةُ رَبِّكَ لَأَمۡلَأَنَّ جَهَنَّمَ مِنَ ٱلۡجِنَّةِ وَٱلنَّاسِ أَجۡمَعِينَ","aya_text_emlaey":"إلا من رحم ربك ولذلك خلقهم وتمت كلمة ربك لأملأن جهنم من الجنة والناس أجمعين","aya_tafseer":"[119] إلا مَن رحم ربك فآمنوا به واتبعوا رسله، فإنهم لا يختلفون في توحيد الله وما جاءت به الرسل من عند الله، وقد اقتضت حكمته سبحانه وتعالى أنه خَلَقهم مختلفين: فريق شقيٌّ وفريق سعيد، وكل ميسَّر لما خُلِق له. وبهذا يتحقق وعد ربك في قضائه وقدره: أنه سبحانه سيملأ جهنم من الجن والإنس الذين اتبعوا إبليس وجنده ولم يهتدوا للإيمان."},{"id":"1593","jozz":"12","page":"235","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"3","line_end":"5","aya_no":"120","aya_text":"وَكُلّٗا نَّقُصُّ عَلَيۡكَ مِنۡ أَنۢبَآءِ ٱلرُّسُلِ مَا نُثَبِّتُ بِهِۦ فُؤَادَكَۚ وَجَآءَكَ فِي هَٰذِهِ ٱلۡحَقُّ وَمَوۡعِظَةٞ وَذِكۡرَىٰ لِلۡمُؤۡمِنِينَ","aya_text_emlaey":"وكلا نقص عليك من أنباء الرسل ما نثبت به فؤادك وجاءك في هذه الحق وموعظة وذكرى للمؤمنين","aya_tafseer":"[120] ونقصُّ عليك -أيها الرسول- من أخبار الرسل الذين كانوا قبلك، كل ما تحتاج إليه مما يقوِّي قلبك للقيام بأعباء الرسالة، وقد جاءك في هذه السورة وما اشتملت عليه من أخبار، بيان الحق الذي أنت عليه، وجاءك فيها موعظة يرتدع بها الكافرون، وذكرى يتذكر بها المؤمنون بالله ورسله."},{"id":"1594","jozz":"12","page":"235","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"5","line_end":"6","aya_no":"121","aya_text":"وَقُل لِّلَّذِينَ لَا يُؤۡمِنُونَ ٱعۡمَلُواْ عَلَىٰ مَكَانَتِكُمۡ إِنَّا عَٰمِلُونَ","aya_text_emlaey":"وقل للذين لا يؤمنون اعملوا على مكانتكم إنا عاملون","aya_tafseer":"[121] وقل -أيها الرسول- للكافرين الذين لا يقرُّون بوحدانية الله: اعملوا ما أنتم عاملون على حالتكم وطريقتكم في مقاومة الدعوة وإيذاء الرسول والمستجيبين له، فإنَّا عاملون على مكانتنا وطريقتنا من الثبات على ديننا وتنفيذ أمر الله."},{"id":"1595","jozz":"12","page":"235","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"6","line_end":"6","aya_no":"122","aya_text":"وَٱنتَظِرُوٓاْ إِنَّا مُنتَظِرُونَ","aya_text_emlaey":"وانتظروا إنا منتظرون","aya_tafseer":"[122] وانتظروا عاقبة أمرنا، فإنَّا منتظرون عاقبة أمركم. وفي هذا تهديد ووعيد لهم."},{"id":"1596","jozz":"12","page":"235","sura_no":"11","sura_name_en":"Hūd","sura_name_ar":"هُود ","line_start":"7","line_end":"8","aya_no":"123","aya_text":"وَلِلَّهِ غَيۡبُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَإِلَيۡهِ يُرۡجَعُ ٱلۡأَمۡرُ كُلُّهُۥ فَٱعۡبُدۡهُ وَتَوَكَّلۡ عَلَيۡهِۚ وَمَا رَبُّكَ بِغَٰفِلٍ عَمَّا تَعۡمَلُونَ","aya_text_emlaey":"ولله غيب السموات والأرض وإليه يرجع الأمر كله فاعبده وتوكل عليه وما ربك بغافل عما تعملون","aya_tafseer":"[123] ولله سبحانه وتعالى عِلْمُ كلِّ ما غاب في السموات والأرض، وإليه يُرْجَع الأمر كله يوم القيامة، فاعبده -أيها النبي- وفوِّض أمرك إليه، وما ربك بغافل عما تعملون من الخير والشر، وسيجازي كُلّاً بعمله."}]
